BEGIN;
CREATE TEMP TABLE legacy_guides(payload jsonb NOT NULL) ON COMMIT DROP;
INSERT INTO legacy_guides(payload) VALUES ($legacy_payload$[{"slug":"data-analytics","task_number":1,"title":"Dataset Cleaning","old_description":"[[AZ]]\nAnaliz üçün verilənlər dəstini təmizlə, çevrilmələri sənədləşdir və əvvəl/sonra keyfiyyəti ölç.\n\n[[EN]]\nClean an analysis dataset, document transformations, and measure quality before and after.","old_instructions":"[[AZ]]\n## 1. Bu tapşırıq nə üçündür?\nCSV faylındakı səhv və qarışıq məlumatları təmizləyib analizə hazırlayacaqsan. Təmizləmədən əvvəl və sonra məlumat keyfiyyətini müqayisə edəcəksən.\n\n## 2. Başlamazdan əvvəl\nCSV, sətir və sütun anlayışları, Excel/Google Sheets-in əsasları. Python biliyi faydalıdır, amma ilkin yoxlamanı cədvəl proqramında da edə bilərsən. Yalnız uydurma məlumat istifadə et.\n\n## 3. Addım-addım icra\n1. GitHub-da özünə boş `dataset-cleaning` repo-su yarat; `data` və `reports` qovluqları əlavə et. Sıfırdan başla.\n2. Ən azı 100 sətirlik uydurma CSV yarat. Boş xanalar, təkrar sətirlər, səhv tarixlər və müxtəlif yazılışlı kateqoriyalar daxil et.\n3. `README.md` və `data-dictionary.md` fayllarında sütunları izah et.\n4. Orijinal CSV-ni dəyişmədən saxla, təmizlənmiş versiyanı ayrı fayla yaz.\n5. Boş dəyərlər, təkrarlar və səhv tarixlər üçün qaydalar seç və səbəbini qeyd et.\n6. Əvvəl/sonra sətir sayını, boş dəyərləri və təkrarları müqayisə et.\n7. Nəticələri `reports/summary.md`-də yaz və repo-nu GitHub-a göndər.\n\n## 4. Konkret nümunə və izah\nMəsələn, CSV sütunları `application_id`, `created_at`, `status`, `score` olsun. `accepted`, `Accepted` yazılışlarını eyniləşdir; təkrar ID və oxunmayan tarix üçün seçdiyin qaydanı yaz. Bütün sütunu səbəbsiz silmə.\n\n## 5. Nə təhvil verməlisən?\nÖz GitHub repo linkin, orijinal və təmiz CSV, sütun izahları, təmizləmə qaydaları və əvvəl/sonra müqayisə hesabatı.\n\n## 6. Hazır olduğunu necə yoxlamalısan?\nOrijinal CSV dəyişməyib. Problem növləri və sətir sayları əvvəl/sonra göstərilib; təmizləmə addımları təkrar icra edilə bilir.\n\n[[EN]]\n## 1. Goal\nClean incorrect or inconsistent values in a CSV file and prepare it for analysis. Compare data quality before and after cleaning.\n\n## 2. Before you start\nCSV files, rows and columns, and basic Excel/Google Sheets use. Python helps, but you can inspect the data in a spreadsheet first. Use fictional data only.\n\n## 3. Step-by-step work\n1. Create your own empty GitHub repository named `dataset-cleaning` and add `data` and `reports` folders. Start from scratch.\n2. Create a fictional CSV with at least 100 rows. Include empty cells, duplicates, invalid dates, and inconsistent category spelling.\n3. Explain the columns in `README.md` and `data-dictionary.md`.\n4. Keep the original CSV unchanged and save the cleaned version separately.\n5. Choose rules for missing values, duplicates, and invalid dates; explain why.\n6. Compare row counts, missing values, and duplicates before and after cleaning.\n7. Write findings in `reports/summary.md` and push the repository to GitHub.\n\n## 4. Concrete example and explanation\nUse fictional columns such as `application_id`, `created_at`, `status`, and `score`. Normalize accepted/Accepted and document rules for duplicate IDs and invalid dates. Do not remove columns without justification.\n\n## 5. What to submit\nYour own GitHub repository link, original and cleaned CSV files, column explanations, cleaning rules, and a before/after report.\n\n## 6. How to check your work\nKeep the original CSV untouched. Show before/after row counts and issue counts; make cleaning steps reproducible.","new_description":"[[AZ]]\nAnaliz üçün verilənlər dəstini təmizlə, çevrilmələri sənədləşdir və əvvəl/sonra keyfiyyəti ölç.\n\nPulsuz alətlər: Python (free), pandas (open source), Google Sheets (personal). Geniş bələdçi tapşırığın içindədir.\n\n[[EN]]\nClean an analysis dataset, document transformations, and measure quality before and after.\n\nFree tools: Python (free), pandas (open source), Google Sheets (personal). Find the detailed walkthrough inside the task.","new_instructions":"[[AZ]]\n## Tapşırığın sadə dildə izahı\nMəqsəd bu tapşırığı özün başa düşüb **praktiki işləyən nəticə** hazırlamaqdır. **Nümunə situasiya:** 25 sintetik müraciət sətrində boş tarix, təkrar ID və səhv statusları təmizləyib `clean.csv` çıxart.\n\n## Pulsuz proqramlar və onlardan istifadə\n- **Python (free)** — https://www.python.org. Lokal Python qur, `.py` skriptləri və sintetik testləri terminaldan işlət.\n- **pandas (open source)** — https://pandas.pydata.org. Sintetik CSV-ni DataFrame kimi oxu, boş/dublikat dəyərləri ölç və təmizlə.\n- **Google Sheets (personal)** — https://sheets.google.com. Sütun başlıqları, sintetik sətirlər və yoxlanıla bilən hesablamalar yarat.\n> Real istehsal məlumatı, ödənişli hosting və premium abunə tələb olunmur. Pulsuz limitlər dəyişə bilər; lokal test və sintetik məlumatdan istifadə et.\n\n## Addım-addım işləmə qaydası (8 mərhələ)\n1. Yalnız öz kompüterində `Talora / data-analytics / task-1` qovluğu aç; əvvəlki tapşırıqdakı sintetik məlumat və kodu götür.\n2. Bu işdə hansı problemi həll etdiyini, istifadəçini və yoxlanacaq nəticəni bir cümlə ilə yaz.\n3. `raw.csv` üçün ID, date, status, program sütunlarını hazırla və data dictionary yaz. Qeyd və nəticəni fayl, kod, cədvəl, diaqram və ya ekran görüntüsü ilə sübut et.\n4. Dublikat və boş dəyərləri ayrıca say, hər düzəlişin səbəbini qeyd et. Qeyd və nəticəni fayl, kod, cədvəl, diaqram və ya ekran görüntüsü ilə sübut et.\n5. `clean.csv`-ni ikinci dəfə açaraq sətir sayını və boş dəyər nisbətini müqayisə et. Qeyd və nəticəni fayl, kod, cədvəl, diaqram və ya ekran görüntüsü ilə sübut et.\n6. Praktik nümunəni yerinə yetir: 25 sintetik müraciət sətrində boş tarix, təkrar ID və səhv statusları təmizləyib `clean.csv` çıxart. Ən azı bir düzgün və bir boş/səhv hal üçün gözlənilən nəticəni qeyd et.\n7. Əvvəlki tapşırıq şərtlərində tələb olunan faylı və linki hazırla; mənbə faylı, test nəticəsi və qısa README əlavə et.\n8. Göndərməzdən əvvəl orijinal şərtlərin hər bəndini yoxla, 3–5 cümlədə nəyi öyrəndiyini və məhdudiyyətləri izah et.\n\n## İşlənmiş praktik nümunə\n25 sintetik müraciət sətrində boş tarix, təkrar ID və səhv statusları təmizləyib `clean.csv` çıxart.\nNümunəni öz layihənə uyğun dəyiş, gördüyün nəticəni nə ilə yoxladığını qeyd et. Demo rəqəmləri real statistikaya çevirmə.\n\n## Təhvil veriləcək materiallar\n- **Əsas iş:** aşağıdakı orijinal tapşırıqda tələb olunan fayl, GitHub repo və ya link.\n- **Mənbə və test:** redaktə edilə bilən fayllar, uyğun kod, sintetik data, ekran görüntüsü və ya test nəticəsi.\n- **İzah:** 3–5 cümləlik hesabat, istifadə edilmiş pulsuz alətlər və istinadlar.\n- **Təhlükəsizlik:** heç bir şifrə, API key, şəxsi müraciət məlumatı və ya icazəsiz material paylaşma.\n\n## 100 ballıq praktiki özünü qiymətləndirmə\n- **40 bal:** əsas fəaliyyətlər və rəsmi tələb olunan nəticələr hazırdır.\n- **25 bal:** nəticə işləyir, ölçülüb və mənfi hallar yoxlanıb.\n- **15 bal:** sənəd, fayl adları, README və təqdimat aydındır.\n- **10 bal:** təhlükəsizlik, mənbələr və pulsuz alət qaydalarına əməl olunub.\n- **10 bal:** seçimlərin səbəbi və növbəti təkmilləşdirmələr yazılıb.\n**Bu rubrik öyrənmə üçün nümunədir; əvvəldən qiymətləndirilmiş təqdimatları və rəsmi tapşırıq meyarlarını dəyişmir.**\n\n## Göndərməzdən əvvəl yoxla\n- Yalnız lokal, sintetik və ya istifadəsinə icazə verilmiş məlumat işlənib.\n- Paylaşım linki oxunur, fayl açılır, heç bir məxfi məlumat yoxdur.\n- Əvvəlki rəsmi şərtlərdə göstərilən nəticələr tamdır.\n\n## Əvvəlki rəsmi tapşırıq tələbləri (dəyişməyib)\n## 1. Bu tapşırıq nə üçündür?\nCSV faylındakı səhv və qarışıq məlumatları təmizləyib analizə hazırlayacaqsan. Təmizləmədən əvvəl və sonra məlumat keyfiyyətini müqayisə edəcəksən.\n\n## 2. Başlamazdan əvvəl\nCSV, sətir və sütun anlayışları, Excel/Google Sheets-in əsasları. Python biliyi faydalıdır, amma ilkin yoxlamanı cədvəl proqramında da edə bilərsən. Yalnız uydurma məlumat istifadə et.\n\n## 3. Addım-addım icra\n1. GitHub-da özünə boş `dataset-cleaning` repo-su yarat; `data` və `reports` qovluqları əlavə et. Sıfırdan başla.\n2. Ən azı 100 sətirlik uydurma CSV yarat. Boş xanalar, təkrar sətirlər, səhv tarixlər və müxtəlif yazılışlı kateqoriyalar daxil et.\n3. `README.md` və `data-dictionary.md` fayllarında sütunları izah et.\n4. Orijinal CSV-ni dəyişmədən saxla, təmizlənmiş versiyanı ayrı fayla yaz.\n5. Boş dəyərlər, təkrarlar və səhv tarixlər üçün qaydalar seç və səbəbini qeyd et.\n6. Əvvəl/sonra sətir sayını, boş dəyərləri və təkrarları müqayisə et.\n7. Nəticələri `reports/summary.md`-də yaz və repo-nu GitHub-a göndər.\n\n## 4. Konkret nümunə və izah\nMəsələn, CSV sütunları `application_id`, `created_at`, `status`, `score` olsun. `accepted`, `Accepted` yazılışlarını eyniləşdir; təkrar ID və oxunmayan tarix üçün seçdiyin qaydanı yaz. Bütün sütunu səbəbsiz silmə.\n\n## 5. Nə təhvil verməlisən?\nÖz GitHub repo linkin, orijinal və təmiz CSV, sütun izahları, təmizləmə qaydaları və əvvəl/sonra müqayisə hesabatı.\n\n## 6. Hazır olduğunu necə yoxlamalısan?\nOrijinal CSV dəyişməyib. Problem növləri və sətir sayları əvvəl/sonra göstərilib; təmizləmə addımları təkrar icra edilə bilir.\n\n[[EN]]\n## Beginner explanation\nThe goal is to produce **a real, verifiable outcome** rather than theory alone. **Example scenario:** Clean missing dates, duplicate IDs and inconsistent statuses in 25 fictional applications.\n\n## Free tools and how to start\n- **Python (free)** — https://www.python.org. Install Python locally and run scripts with fictional test fixtures.\n- **pandas (open source)** — https://pandas.pydata.org. Read fictional CSV data into a DataFrame and inspect missing/duplicate values.\n- **Google Sheets (personal)** — https://sheets.google.com. Create labeled columns, fictional sample records and verifiable calculations.\n> No production data, paid hosting or premium subscription is required. Free quotas may change; use local tests and fictional data.\n\n## Step-by-step procedure (8 stages)\n1. Create a local `Talora / data-analytics / task-1` folder and reuse earlier fictional data or source files.\n2. Summarize the user, the problem and a verifiable success criterion in one sentence.\n3. Create a raw.csv with ID, date, status and program fields and a data dictionary. Include evidence in a file, source code, sheet, diagram or screenshot.\n4. Count duplicates and missing values; document each cleaning rule. Include evidence in a file, source code, sheet, diagram or screenshot.\n5. Reopen clean.csv and verify row counts and missing-value rates. Include evidence in a file, source code, sheet, diagram or screenshot.\n6. Complete this worked example: Clean missing dates, duplicate IDs and inconsistent statuses in 25 fictional applications. Note one valid and one invalid/empty case.\n7. Prepare the deliverable required by the original instructions with editable sources, tests and a short README.\n8. Before submitting, check the original criteria and write a three-to-five sentence conclusion and limitations.\n\n## Practical worked example\nClean missing dates, duplicate IDs and inconsistent statuses in 25 fictional applications.\nAdapt the example to your own project, verify the result and do not present fictional statistics as real.\n\n## Required submission\n- **Main result:** the file, repository or link required by the unchanged original assignment below.\n- **Source and tests:** editable materials, appropriate code, fictional data, screenshots or test evidence.\n- **Explanation:** three to five sentences on findings, free tools and citations.\n- **Safety:** no passwords, API keys, private applications or unlicensed content.\n\n## Self-assessment rubric (100 points)\n- **40:** complete core actions and original deliverables.\n- **25:** measured, working result and invalid-case testing.\n- **15:** readable files, README and structure.\n- **10:** security, citations and free tools.\n- **10:** clear reasoning and suggested next steps.\n**Illustrative learning rubric only: it does not change official criteria or previously graded work.**\n\n## Before submission\n- Use local, fictional or properly authorized data.\n- Check links, exports and absence of confidential information.\n- Verify all original official requirements below.\n\n## Original official requirements (unchanged)\n## 1. Goal\nClean incorrect or inconsistent values in a CSV file and prepare it for analysis. Compare data quality before and after cleaning.\n\n## 2. Before you start\nCSV files, rows and columns, and basic Excel/Google Sheets use. Python helps, but you can inspect the data in a spreadsheet first. Use fictional data only.\n\n## 3. Step-by-step work\n1. Create your own empty GitHub repository named `dataset-cleaning` and add `data` and `reports` folders. Start from scratch.\n2. Create a fictional CSV with at least 100 rows. Include empty cells, duplicates, invalid dates, and inconsistent category spelling.\n3. Explain the columns in `README.md` and `data-dictionary.md`.\n4. Keep the original CSV unchanged and save the cleaned version separately.\n5. Choose rules for missing values, duplicates, and invalid dates; explain why.\n6. Compare row counts, missing values, and duplicates before and after cleaning.\n7. Write findings in `reports/summary.md` and push the repository to GitHub.\n\n## 4. Concrete example and explanation\nUse fictional columns such as `application_id`, `created_at`, `status`, and `score`. Normalize accepted/Accepted and document rules for duplicate IDs and invalid dates. Do not remove columns without justification.\n\n## 5. What to submit\nYour own GitHub repository link, original and cleaned CSV files, column explanations, cleaning rules, and a before/after report.\n\n## 6. How to check your work\nKeep the original CSV untouched. Show before/after row counts and issue counts; make cleaning steps reproducible."},{"slug":"data-analytics","task_number":2,"title":"SQL KPI Analysis","old_description":"[[AZ]]\nSQL ilə təcrübə müraciətlərinin həftəlik funnel və əsas performans göstəricilərini hesabla.\n\n[[EN]]\nUse SQL to calculate a weekly application funnel and its key performance indicators.","old_instructions":"[[AZ]]\n## 1. Bu tapşırıq nə üçündür?\nSQL ilə əsas KPI-ları hesablayıb biznes sualına cavab verəcəksən.\n\n## 2. Başlamazdan əvvəl\nTapşırıq 1-dəki öz data repo-n, SELECT, WHERE, GROUP BY, JOIN və aggregate funksiyalarının əsasları. Yalnız sintetik məlumat istifadə et.\n\n## 3. Addım-addım icra\n1. Öz data repo-nu davam etdir.\n2. Layihə/müraciət kimi bir mövzu üçün sintetik cədvəl və ən azı 100 sətir hazırla.\n3. 3–5 KPI müəyyən et və hər KPI-nın biznes mənasını izah et.\n4. SQL sorğuları ilə KPI-ları hesabla; NULL və duplicate halları yoxla.\n5. Nəticələri cədvəldə göstər və hesablamaları manual sample ilə yoxla.\n6. Sorğuları və data dictionary-ni README-də sənədləşdir.\n\n## 4. Konkret nümunə və izah\nKPI əsas nəticəni ölçən göstəricidir. Məsələn, qəbul faizi = qəbul olunmuş müraciət sayı / ümumi müraciət sayı × 100. 10 müraciətdən 4-ü qəbul olunubsa nəticə 40%-dir. Məxrəc sıfır olduqda nə qaytaracağını ayrıca müəyyən et.\n\n## 5. Nə təhvil verməlisən?\nÖz GitHub repo linkin, schema/seed data, SQL faylları, KPI cədvəli və izah. KPI-lar təkrar hesablana bilməli və formulaları aydın olmalıdır.\n\n## 6. Hazır olduğunu necə yoxlamalısan?\n3–5 KPI üçün formula, vahid və biznes mənası var. SQL nəticəsi əl ilə yoxlanmış kiçik nümunə ilə uyğundur; NULL və təkrar ID sayları şişirtmir.\n\n[[EN]]\n## 1. Goal\nCalculate key performance indicators (KPIs) with SQL and answer a business question.\n\n## 2. Before you start\nYour data repository from Task 1, basic SELECT, WHERE, GROUP BY, JOIN, and aggregate functions. Use synthetic data only.\n\n## 3. Step-by-step work\n1. Continue your own data repository.\n2. Create a synthetic table with at least 100 rows for a topic such as projects/applications.\n3. Define three to five KPIs and explain their business meaning.\n4. Calculate KPIs with SQL and check NULL/duplicate cases.\n5. Present results in a table and verify calculations with a manual sample.\n6. Document queries and the data dictionary in the README.\n\n## 4. Concrete example and explanation\nA KPI measures an important outcome. Acceptance rate = accepted applications / all applications × 100; four of ten gives 40%. Define behavior when the denominator is zero.\n\n## 5. What to submit\nYour own GitHub repository link, schema/seed data, SQL files, KPI table, and explanation. KPIs must be reproducible with clear formulas.\n\n## 6. How to check your work\nDocument formula, units, and business meaning for 3–5 KPIs. Verify a small sample manually; NULLs and duplicate IDs cannot inflate counts.","new_description":"[[AZ]]\nSQL ilə təcrübə müraciətlərinin həftəlik funnel və əsas performans göstəricilərini hesabla.\n\nPulsuz alətlər: SQLite (free), Google Sheets (personal). Geniş bələdçi tapşırığın içindədir.\n\n[[EN]]\nUse SQL to calculate a weekly application funnel and its key performance indicators.\n\nFree tools: SQLite (free), Google Sheets (personal). Find the detailed walkthrough inside the task.","new_instructions":"[[AZ]]\n## Tapşırığın sadə dildə izahı\nMəqsəd bu tapşırığı özün başa düşüb **praktiki işləyən nəticə** hazırlamaqdır. **Nümunə situasiya:** 20 uydurma müraciətdə `approved / total` nisbətini SQL ilə hesabla; sıfır bölünməsini yoxla.\n\n## Pulsuz proqramlar və onlardan istifadə\n- **SQLite (free)** — https://www.sqlite.org. Lokal `.db` faylında sintetik cədvəl, SQL sorğuları və testlər hazırla.\n- **Google Sheets (personal)** — https://sheets.google.com. Sütun başlıqları, sintetik sətirlər və yoxlanıla bilən hesablamalar yarat.\n> Real istehsal məlumatı, ödənişli hosting və premium abunə tələb olunmur. Pulsuz limitlər dəyişə bilər; lokal test və sintetik məlumatdan istifadə et.\n\n## Addım-addım işləmə qaydası (8 mərhələ)\n1. Yalnız öz kompüterində `Talora / data-analytics / task-2` qovluğu aç; əvvəlki tapşırıqdakı sintetik məlumat və kodu götür.\n2. Bu işdə hansı problemi həll etdiyini, istifadəçini və yoxlanacaq nəticəni bir cümlə ilə yaz.\n3. SQLite-də kiçik `applications` cədvəli və sintetik INSERT nümunələri yarat. Qeyd və nəticəni fayl, kod, cədvəl, diaqram və ya ekran görüntüsü ilə sübut et.\n4. COUNT və CASE ilə status üzrə say və qəbul faizini hesabla. Qeyd və nəticəni fayl, kod, cədvəl, diaqram və ya ekran görüntüsü ilə sübut et.\n5. SQL nəticəsini Sheets-də ayrıca hesablayıb uyğunluğunu təsdiqlə. Qeyd və nəticəni fayl, kod, cədvəl, diaqram və ya ekran görüntüsü ilə sübut et.\n6. Praktik nümunəni yerinə yetir: 20 uydurma müraciətdə `approved / total` nisbətini SQL ilə hesabla; sıfır bölünməsini yoxla. Ən azı bir düzgün və bir boş/səhv hal üçün gözlənilən nəticəni qeyd et.\n7. Əvvəlki tapşırıq şərtlərində tələb olunan faylı və linki hazırla; mənbə faylı, test nəticəsi və qısa README əlavə et.\n8. Göndərməzdən əvvəl orijinal şərtlərin hər bəndini yoxla, 3–5 cümlədə nəyi öyrəndiyini və məhdudiyyətləri izah et.\n\n## İşlənmiş praktik nümunə\n20 uydurma müraciətdə `approved / total` nisbətini SQL ilə hesabla; sıfır bölünməsini yoxla.\nNümunəni öz layihənə uyğun dəyiş, gördüyün nəticəni nə ilə yoxladığını qeyd et. Demo rəqəmləri real statistikaya çevirmə.\n\n## Təhvil veriləcək materiallar\n- **Əsas iş:** aşağıdakı orijinal tapşırıqda tələb olunan fayl, GitHub repo və ya link.\n- **Mənbə və test:** redaktə edilə bilən fayllar, uyğun kod, sintetik data, ekran görüntüsü və ya test nəticəsi.\n- **İzah:** 3–5 cümləlik hesabat, istifadə edilmiş pulsuz alətlər və istinadlar.\n- **Təhlükəsizlik:** heç bir şifrə, API key, şəxsi müraciət məlumatı və ya icazəsiz material paylaşma.\n\n## 100 ballıq praktiki özünü qiymətləndirmə\n- **40 bal:** əsas fəaliyyətlər və rəsmi tələb olunan nəticələr hazırdır.\n- **25 bal:** nəticə işləyir, ölçülüb və mənfi hallar yoxlanıb.\n- **15 bal:** sənəd, fayl adları, README və təqdimat aydındır.\n- **10 bal:** təhlükəsizlik, mənbələr və pulsuz alət qaydalarına əməl olunub.\n- **10 bal:** seçimlərin səbəbi və növbəti təkmilləşdirmələr yazılıb.\n**Bu rubrik öyrənmə üçün nümunədir; əvvəldən qiymətləndirilmiş təqdimatları və rəsmi tapşırıq meyarlarını dəyişmir.**\n\n## Göndərməzdən əvvəl yoxla\n- Yalnız lokal, sintetik və ya istifadəsinə icazə verilmiş məlumat işlənib.\n- Paylaşım linki oxunur, fayl açılır, heç bir məxfi məlumat yoxdur.\n- Əvvəlki rəsmi şərtlərdə göstərilən nəticələr tamdır.\n\n## Əvvəlki rəsmi tapşırıq tələbləri (dəyişməyib)\n## 1. Bu tapşırıq nə üçündür?\nSQL ilə əsas KPI-ları hesablayıb biznes sualına cavab verəcəksən.\n\n## 2. Başlamazdan əvvəl\nTapşırıq 1-dəki öz data repo-n, SELECT, WHERE, GROUP BY, JOIN və aggregate funksiyalarının əsasları. Yalnız sintetik məlumat istifadə et.\n\n## 3. Addım-addım icra\n1. Öz data repo-nu davam etdir.\n2. Layihə/müraciət kimi bir mövzu üçün sintetik cədvəl və ən azı 100 sətir hazırla.\n3. 3–5 KPI müəyyən et və hər KPI-nın biznes mənasını izah et.\n4. SQL sorğuları ilə KPI-ları hesabla; NULL və duplicate halları yoxla.\n5. Nəticələri cədvəldə göstər və hesablamaları manual sample ilə yoxla.\n6. Sorğuları və data dictionary-ni README-də sənədləşdir.\n\n## 4. Konkret nümunə və izah\nKPI əsas nəticəni ölçən göstəricidir. Məsələn, qəbul faizi = qəbul olunmuş müraciət sayı / ümumi müraciət sayı × 100. 10 müraciətdən 4-ü qəbul olunubsa nəticə 40%-dir. Məxrəc sıfır olduqda nə qaytaracağını ayrıca müəyyən et.\n\n## 5. Nə təhvil verməlisən?\nÖz GitHub repo linkin, schema/seed data, SQL faylları, KPI cədvəli və izah. KPI-lar təkrar hesablana bilməli və formulaları aydın olmalıdır.\n\n## 6. Hazır olduğunu necə yoxlamalısan?\n3–5 KPI üçün formula, vahid və biznes mənası var. SQL nəticəsi əl ilə yoxlanmış kiçik nümunə ilə uyğundur; NULL və təkrar ID sayları şişirtmir.\n\n[[EN]]\n## Beginner explanation\nThe goal is to produce **a real, verifiable outcome** rather than theory alone. **Example scenario:** Calculate approval rate on 20 fictional applications using SQL and safe denominator handling.\n\n## Free tools and how to start\n- **SQLite (free)** — https://www.sqlite.org. Use a local .db database with fictional tables, queries and tests.\n- **Google Sheets (personal)** — https://sheets.google.com. Create labeled columns, fictional sample records and verifiable calculations.\n> No production data, paid hosting or premium subscription is required. Free quotas may change; use local tests and fictional data.\n\n## Step-by-step procedure (8 stages)\n1. Create a local `Talora / data-analytics / task-2` folder and reuse earlier fictional data or source files.\n2. Summarize the user, the problem and a verifiable success criterion in one sentence.\n3. Create a small applications table in local SQLite and populate fictional rows. Include evidence in a file, source code, sheet, diagram or screenshot.\n4. Use COUNT and CASE to compute status totals and approval rate. Include evidence in a file, source code, sheet, diagram or screenshot.\n5. Independently verify results in Sheets and document any discrepancies. Include evidence in a file, source code, sheet, diagram or screenshot.\n6. Complete this worked example: Calculate approval rate on 20 fictional applications using SQL and safe denominator handling. Note one valid and one invalid/empty case.\n7. Prepare the deliverable required by the original instructions with editable sources, tests and a short README.\n8. Before submitting, check the original criteria and write a three-to-five sentence conclusion and limitations.\n\n## Practical worked example\nCalculate approval rate on 20 fictional applications using SQL and safe denominator handling.\nAdapt the example to your own project, verify the result and do not present fictional statistics as real.\n\n## Required submission\n- **Main result:** the file, repository or link required by the unchanged original assignment below.\n- **Source and tests:** editable materials, appropriate code, fictional data, screenshots or test evidence.\n- **Explanation:** three to five sentences on findings, free tools and citations.\n- **Safety:** no passwords, API keys, private applications or unlicensed content.\n\n## Self-assessment rubric (100 points)\n- **40:** complete core actions and original deliverables.\n- **25:** measured, working result and invalid-case testing.\n- **15:** readable files, README and structure.\n- **10:** security, citations and free tools.\n- **10:** clear reasoning and suggested next steps.\n**Illustrative learning rubric only: it does not change official criteria or previously graded work.**\n\n## Before submission\n- Use local, fictional or properly authorized data.\n- Check links, exports and absence of confidential information.\n- Verify all original official requirements below.\n\n## Original official requirements (unchanged)\n## 1. Goal\nCalculate key performance indicators (KPIs) with SQL and answer a business question.\n\n## 2. Before you start\nYour data repository from Task 1, basic SELECT, WHERE, GROUP BY, JOIN, and aggregate functions. Use synthetic data only.\n\n## 3. Step-by-step work\n1. Continue your own data repository.\n2. Create a synthetic table with at least 100 rows for a topic such as projects/applications.\n3. Define three to five KPIs and explain their business meaning.\n4. Calculate KPIs with SQL and check NULL/duplicate cases.\n5. Present results in a table and verify calculations with a manual sample.\n6. Document queries and the data dictionary in the README.\n\n## 4. Concrete example and explanation\nA KPI measures an important outcome. Acceptance rate = accepted applications / all applications × 100; four of ten gives 40%. Define behavior when the denominator is zero.\n\n## 5. What to submit\nYour own GitHub repository link, schema/seed data, SQL files, KPI table, and explanation. KPIs must be reproducible with clear formulas.\n\n## 6. How to check your work\nDocument formula, units, and business meaning for 3–5 KPIs. Verify a small sample manually; NULLs and duplicate IDs cannot inflate counts."},{"slug":"data-analytics","task_number":3,"title":"Insight Dashboard","old_description":"[[AZ]]\nQərar verən üçün müraciət funnel-ını göstərən interaktiv dashboard prototipi hazırla.\n\n[[EN]]\nBuild an interactive dashboard prototype that explains the application funnel to decision-makers.","old_instructions":"[[AZ]]\n## 1. Bu tapşırıq nə üçündür?\nKPI-ları istifadəçinin tez anlaya biləcəyi dashboard-a çevirəcəksən.\n\n## 2. Başlamazdan əvvəl\nÖz KPI sorğuların, cədvəl/chart əsasları və dashboard aləti (Excel, Google Sheets, Python və ya başqa pulsuz alət).\n\n## 3. Addım-addım icra\n1. Öz data repo-nu davam etdir.\n2. Tapşırıq 2-də hesabladığın KPI-lardan 3–5-ni seç.\n3. Hər KPI üçün uyğun vizual seç; müqayisə üçün bar chart, zaman üzrə dəyişiklik üçün line chart istifadə edə bilərsən.\n4. Filtr və tarix aralığı varsa, onun nəticəyə təsirini aydın göstər.\n5. Başlıq, vahid, mənbə və yenilənmə vaxtını qeyd et.\n6. Chart-ların rəqəmlərini SQL nəticəsi ilə müqayisə et.\n\n## 4. Konkret nümunə və izah\nDashboard göstəriciləri bir ekranda göstərən paneldir. Statuslar üzrə müraciət sayını sütun qrafikində, aylıq müraciət sayını xətt qrafikində göstər. Hər qrafikin başlığı, vahidi və mənbə cədvəli olsun.\n\n## 5. Nə təhvil verməlisən?\nÖz GitHub repo linkin, dashboard faylı/linki, screenshot və KPI izahları. Qrafiklər düzgün etiketlənməli və rəqəmlər sorğu nəticələri ilə uyğun olmalıdır.\n\n## 6. Hazır olduğunu necə yoxlamalısan?\n3–5 göstərici SQL-lə uyğun gəlir. Filtr tətbiq olunursa onun təsiri görünür; hər vizualın hansı suala cavab verdiyi yazılıb.\n\n[[EN]]\n## 1. Goal\nTurn your KPIs into a dashboard that users can understand quickly.\n\n## 2. Before you start\nYour KPI queries, basic tables/charts, and a dashboard tool such as Excel, Google Sheets, Python, or another free tool.\n\n## 3. Step-by-step work\n1. Continue your own data repository.\n2. Choose three to five KPIs from Task 2.\n3. Select suitable visuals; for example, bars for comparisons and lines for trends over time.\n4. If you add filters/date ranges, show how they affect the results.\n5. Label titles, units, data source, and refresh time.\n6. Compare chart values with the SQL results.\n\n## 4. Concrete example and explanation\nA dashboard presents metrics in one view. Use bars for counts by status and a line for monthly counts. Give every chart a title, unit, and source table.\n\n## 5. What to submit\nYour own GitHub repository link, dashboard file/link, screenshot, and KPI explanations. Charts must be clearly labelled and match the query results.\n\n## 6. How to check your work\nMatch 3–5 metrics to SQL results. Show filter effects and state the question answered by each visual.","new_description":"[[AZ]]\nQərar verən üçün müraciət funnel-ını göstərən interaktiv dashboard prototipi hazırla.\n\nPulsuz alətlər: Python (free), pandas (open source), Matplotlib (open source). Geniş bələdçi tapşırığın içindədir.\n\n[[EN]]\nBuild an interactive dashboard prototype that explains the application funnel to decision-makers.\n\nFree tools: Python (free), pandas (open source), Matplotlib (open source). Find the detailed walkthrough inside the task.","new_instructions":"[[AZ]]\n## Tapşırığın sadə dildə izahı\nMəqsəd bu tapşırığı özün başa düşüb **praktiki işləyən nəticə** hazırlamaqdır. **Nümunə situasiya:** Təcrübə kateqoriyaları üzrə say və müraciət faizi üçün iki diaqramlı lokal dashboard hazırla.\n\n## Pulsuz proqramlar və onlardan istifadə\n- **Python (free)** — https://www.python.org. Lokal Python qur, `.py` skriptləri və sintetik testləri terminaldan işlət.\n- **pandas (open source)** — https://pandas.pydata.org. Sintetik CSV-ni DataFrame kimi oxu, boş/dublikat dəyərləri ölç və təmizlə.\n- **Matplotlib (open source)** — https://matplotlib.org. Sintetik datadan qrafik çək, ox adlarını və vahidi qeyd et.\n> Real istehsal məlumatı, ödənişli hosting və premium abunə tələb olunmur. Pulsuz limitlər dəyişə bilər; lokal test və sintetik məlumatdan istifadə et.\n\n## Addım-addım işləmə qaydası (8 mərhələ)\n1. Yalnız öz kompüterində `Talora / data-analytics / task-3` qovluğu aç; əvvəlki tapşırıqdakı sintetik məlumat və kodu götür.\n2. Bu işdə hansı problemi həll etdiyini, istifadəçini və yoxlanacaq nəticəni bir cümlə ilə yaz.\n3. 5 kateqoriyalı sintetik cədvəl seç və KPI təriflərini yaz. Qeyd və nəticəni fayl, kod, cədvəl, diaqram və ya ekran görüntüsü ilə sübut et.\n4. Matplotlib və ya Sheets chart ilə sütun qrafiki və trend qur. Qeyd və nəticəni fayl, kod, cədvəl, diaqram və ya ekran görüntüsü ilə sübut et.\n5. Ox adlarını, ölçü vahidini və mənbənin sintetik olduğunu göstər. Qeyd və nəticəni fayl, kod, cədvəl, diaqram və ya ekran görüntüsü ilə sübut et.\n6. Praktik nümunəni yerinə yetir: Təcrübə kateqoriyaları üzrə say və müraciət faizi üçün iki diaqramlı lokal dashboard hazırla. Ən azı bir düzgün və bir boş/səhv hal üçün gözlənilən nəticəni qeyd et.\n7. Əvvəlki tapşırıq şərtlərində tələb olunan faylı və linki hazırla; mənbə faylı, test nəticəsi və qısa README əlavə et.\n8. Göndərməzdən əvvəl orijinal şərtlərin hər bəndini yoxla, 3–5 cümlədə nəyi öyrəndiyini və məhdudiyyətləri izah et.\n\n## İşlənmiş praktik nümunə\nTəcrübə kateqoriyaları üzrə say və müraciət faizi üçün iki diaqramlı lokal dashboard hazırla.\nNümunəni öz layihənə uyğun dəyiş, gördüyün nəticəni nə ilə yoxladığını qeyd et. Demo rəqəmləri real statistikaya çevirmə.\n\n## Təhvil veriləcək materiallar\n- **Əsas iş:** aşağıdakı orijinal tapşırıqda tələb olunan fayl, GitHub repo və ya link.\n- **Mənbə və test:** redaktə edilə bilən fayllar, uyğun kod, sintetik data, ekran görüntüsü və ya test nəticəsi.\n- **İzah:** 3–5 cümləlik hesabat, istifadə edilmiş pulsuz alətlər və istinadlar.\n- **Təhlükəsizlik:** heç bir şifrə, API key, şəxsi müraciət məlumatı və ya icazəsiz material paylaşma.\n\n## 100 ballıq praktiki özünü qiymətləndirmə\n- **40 bal:** əsas fəaliyyətlər və rəsmi tələb olunan nəticələr hazırdır.\n- **25 bal:** nəticə işləyir, ölçülüb və mənfi hallar yoxlanıb.\n- **15 bal:** sənəd, fayl adları, README və təqdimat aydındır.\n- **10 bal:** təhlükəsizlik, mənbələr və pulsuz alət qaydalarına əməl olunub.\n- **10 bal:** seçimlərin səbəbi və növbəti təkmilləşdirmələr yazılıb.\n**Bu rubrik öyrənmə üçün nümunədir; əvvəldən qiymətləndirilmiş təqdimatları və rəsmi tapşırıq meyarlarını dəyişmir.**\n\n## Göndərməzdən əvvəl yoxla\n- Yalnız lokal, sintetik və ya istifadəsinə icazə verilmiş məlumat işlənib.\n- Paylaşım linki oxunur, fayl açılır, heç bir məxfi məlumat yoxdur.\n- Əvvəlki rəsmi şərtlərdə göstərilən nəticələr tamdır.\n\n## Əvvəlki rəsmi tapşırıq tələbləri (dəyişməyib)\n## 1. Bu tapşırıq nə üçündür?\nKPI-ları istifadəçinin tez anlaya biləcəyi dashboard-a çevirəcəksən.\n\n## 2. Başlamazdan əvvəl\nÖz KPI sorğuların, cədvəl/chart əsasları və dashboard aləti (Excel, Google Sheets, Python və ya başqa pulsuz alət).\n\n## 3. Addım-addım icra\n1. Öz data repo-nu davam etdir.\n2. Tapşırıq 2-də hesabladığın KPI-lardan 3–5-ni seç.\n3. Hər KPI üçün uyğun vizual seç; müqayisə üçün bar chart, zaman üzrə dəyişiklik üçün line chart istifadə edə bilərsən.\n4. Filtr və tarix aralığı varsa, onun nəticəyə təsirini aydın göstər.\n5. Başlıq, vahid, mənbə və yenilənmə vaxtını qeyd et.\n6. Chart-ların rəqəmlərini SQL nəticəsi ilə müqayisə et.\n\n## 4. Konkret nümunə və izah\nDashboard göstəriciləri bir ekranda göstərən paneldir. Statuslar üzrə müraciət sayını sütun qrafikində, aylıq müraciət sayını xətt qrafikində göstər. Hər qrafikin başlığı, vahidi və mənbə cədvəli olsun.\n\n## 5. Nə təhvil verməlisən?\nÖz GitHub repo linkin, dashboard faylı/linki, screenshot və KPI izahları. Qrafiklər düzgün etiketlənməli və rəqəmlər sorğu nəticələri ilə uyğun olmalıdır.\n\n## 6. Hazır olduğunu necə yoxlamalısan?\n3–5 göstərici SQL-lə uyğun gəlir. Filtr tətbiq olunursa onun təsiri görünür; hər vizualın hansı suala cavab verdiyi yazılıb.\n\n[[EN]]\n## Beginner explanation\nThe goal is to produce **a real, verifiable outcome** rather than theory alone. **Example scenario:** Build a local two-chart dashboard for internship counts and fictional application rates.\n\n## Free tools and how to start\n- **Python (free)** — https://www.python.org. Install Python locally and run scripts with fictional test fixtures.\n- **pandas (open source)** — https://pandas.pydata.org. Read fictional CSV data into a DataFrame and inspect missing/duplicate values.\n- **Matplotlib (open source)** — https://matplotlib.org. Chart fictional data with meaningful axis labels and units.\n> No production data, paid hosting or premium subscription is required. Free quotas may change; use local tests and fictional data.\n\n## Step-by-step procedure (8 stages)\n1. Create a local `Talora / data-analytics / task-3` folder and reuse earlier fictional data or source files.\n2. Summarize the user, the problem and a verifiable success criterion in one sentence.\n3. Define KPIs from a five-category fictional dataset. Include evidence in a file, source code, sheet, diagram or screenshot.\n4. Draw a bar chart and trend using Matplotlib or Sheets. Include evidence in a file, source code, sheet, diagram or screenshot.\n5. Label axes, units and synthetic data sources clearly. Include evidence in a file, source code, sheet, diagram or screenshot.\n6. Complete this worked example: Build a local two-chart dashboard for internship counts and fictional application rates. Note one valid and one invalid/empty case.\n7. Prepare the deliverable required by the original instructions with editable sources, tests and a short README.\n8. Before submitting, check the original criteria and write a three-to-five sentence conclusion and limitations.\n\n## Practical worked example\nBuild a local two-chart dashboard for internship counts and fictional application rates.\nAdapt the example to your own project, verify the result and do not present fictional statistics as real.\n\n## Required submission\n- **Main result:** the file, repository or link required by the unchanged original assignment below.\n- **Source and tests:** editable materials, appropriate code, fictional data, screenshots or test evidence.\n- **Explanation:** three to five sentences on findings, free tools and citations.\n- **Safety:** no passwords, API keys, private applications or unlicensed content.\n\n## Self-assessment rubric (100 points)\n- **40:** complete core actions and original deliverables.\n- **25:** measured, working result and invalid-case testing.\n- **15:** readable files, README and structure.\n- **10:** security, citations and free tools.\n- **10:** clear reasoning and suggested next steps.\n**Illustrative learning rubric only: it does not change official criteria or previously graded work.**\n\n## Before submission\n- Use local, fictional or properly authorized data.\n- Check links, exports and absence of confidential information.\n- Verify all original official requirements below.\n\n## Original official requirements (unchanged)\n## 1. Goal\nTurn your KPIs into a dashboard that users can understand quickly.\n\n## 2. Before you start\nYour KPI queries, basic tables/charts, and a dashboard tool such as Excel, Google Sheets, Python, or another free tool.\n\n## 3. Step-by-step work\n1. Continue your own data repository.\n2. Choose three to five KPIs from Task 2.\n3. Select suitable visuals; for example, bars for comparisons and lines for trends over time.\n4. If you add filters/date ranges, show how they affect the results.\n5. Label titles, units, data source, and refresh time.\n6. Compare chart values with the SQL results.\n\n## 4. Concrete example and explanation\nA dashboard presents metrics in one view. Use bars for counts by status and a line for monthly counts. Give every chart a title, unit, and source table.\n\n## 5. What to submit\nYour own GitHub repository link, dashboard file/link, screenshot, and KPI explanations. Charts must be clearly labelled and match the query results.\n\n## 6. How to check your work\nMatch 3–5 metrics to SQL results. Show filter effects and state the question answered by each visual."},{"slug":"data-analytics","task_number":4,"title":"Integrated Data Case Study","old_description":"[[AZ]]\nMüraciət məlumatından koordinator üçün tövsiyə və məhdudiyyətləri olan tam data case study hazırla.\n\n[[EN]]\nCreate a complete application-data case study with recommendations and limitations for a coordinator.","old_instructions":"[[AZ]]\n## 1. Bu tapşırıq nə üçündür?\nMəlumatdan biznes sualına cavab verən tam case study hazırlayacaqsan.\n\n## 2. Başlamazdan əvvəl\nÖz Tapşırıq 1–3 data layihən, SQL/Python və dashboard nəticələri. Analiz üçün uydurma məlumatdan istifadə edə bilərsən.\n\n## 3. Addım-addım icra\n1. Əvvəlki tapşırıqları öz repo-n və ya notebook-da davam etdir.\n2. Bir konkret biznes sualı və 2–3 yoxlanıla bilən hipotez yaz.\n3. Data quality yoxlaması və exploratory analysis apar.\n4. KPI və dashboard qur, tapıntıların datadan necə çıxdığını göstər.\n5. Məhdudiyyətləri və səbəb-nəticə iddiasının mümkün olub-olmadığını qeyd et.\n6. Nəticələri qeyri-texniki oxucu üçün qısa hesabat kimi yaz.\n\n## 4. Konkret nümunə və izah\nBiznes sualı: “Hansı ayda müraciət çoxdur və qəbul faizi necə dəyişir?” 2–3 ilkin fərziyyə yaz, sonra cədvəl və qrafiklə yoxla. Bu ara nəticələri birləşdirən layihədir; yekun təhvil 10-cu tapşırıqdır.\n\n## 5. Nə təhvil verməlisən?\nÖz GitHub repo linkin, təkrar icra edilən notebook/SQL, dashboard, əsas tapıntılar və məhdudiyyətləri göstərən case-study hesabatı. Dəstəklənməyən nəticə çıxarma.\n\n## 6. Hazır olduğunu necə yoxlamalısan?\nHər tapıntının sorğusu və ya qrafiki göstərilib. İlkin fərziyyə fakt kimi yazılmayıb; məlumatın hansı qərarı dəstəklədiyi və nəyi sübut etmədiyi izah edilib.\n\n[[EN]]\n## 1. Goal\nCreate a complete case study that answers a business question using data.\n\n## 2. Before you start\nYour data project from Tasks 1–3, SQL/Python, and dashboard results. Fictional data is acceptable.\n\n## 3. Step-by-step work\n1. Continue earlier work in your own repository or notebook.\n2. State one business question and two or three testable hypotheses.\n3. Check data quality and perform exploratory analysis.\n4. Build KPIs and a dashboard, showing how findings follow from the data.\n5. State limitations and whether causal claims can be justified.\n6. Write a concise report for a non-technical reader.\n\n## 4. Concrete example and explanation\nExample question: “Which month has the most applications, and how does acceptance rate vary?” Test 2–3 initial hypotheses using tables and charts. Final reproducibility handoff is Task 10.\n\n## 5. What to submit\nYour own GitHub repository link, reproducible notebook/SQL, dashboard, key findings, and case-study report with limitations. Do not make unsupported claims.\n\n## 6. How to check your work\nLink every finding to a query or chart. Do not present initial hypotheses as facts; explain supported decisions and unsupported claims.","new_description":"[[AZ]]\nMüraciət məlumatından koordinator üçün tövsiyə və məhdudiyyətləri olan tam data case study hazırla.\n\nPulsuz alətlər: Python (free), pandas (open source), GitHub Free. Geniş bələdçi tapşırığın içindədir.\n\n[[EN]]\nCreate a complete application-data case study with recommendations and limitations for a coordinator.\n\nFree tools: Python (free), pandas (open source), GitHub Free. Find the detailed walkthrough inside the task.","new_instructions":"[[AZ]]\n## Tapşırığın sadə dildə izahı\nMəqsəd bu tapşırığı özün başa düşüb **praktiki işləyən nəticə** hazırlamaqdır. **Nümunə situasiya:** `raw.csv` → təmizləmə → SQL KPI → chart → nəticə cümləsi axınını README-də təsvir et.\n\n## Pulsuz proqramlar və onlardan istifadə\n- **Python (free)** — https://www.python.org. Lokal Python qur, `.py` skriptləri və sintetik testləri terminaldan işlət.\n- **pandas (open source)** — https://pandas.pydata.org. Sintetik CSV-ni DataFrame kimi oxu, boş/dublikat dəyərləri ölç və təmizlə.\n- **GitHub Free** — https://github.com. README və nümunə kod üçün şəxsi repo yarat; token və şəxsi data yükləmə.\n> Real istehsal məlumatı, ödənişli hosting və premium abunə tələb olunmur. Pulsuz limitlər dəyişə bilər; lokal test və sintetik məlumatdan istifadə et.\n\n## Addım-addım işləmə qaydası (8 mərhələ)\n1. Yalnız öz kompüterində `Talora / data-analytics / task-4` qovluğu aç; əvvəlki tapşırıqdakı sintetik məlumat və kodu götür.\n2. Bu işdə hansı problemi həll etdiyini, istifadəçini və yoxlanacaq nəticəni bir cümlə ilə yaz.\n3. Əvvəlki analiz fayllarını bir `data/` və `notebooks/` strukturuna yığ. Qeyd və nəticəni fayl, kod, cədvəl, diaqram və ya ekran görüntüsü ilə sübut et.\n4. İki ölçü hesabla və bir qrafikdə müqayisə et; ən azı 2 istisna halı yoxla. Qeyd və nəticəni fayl, kod, cədvəl, diaqram və ya ekran görüntüsü ilə sübut et.\n5. 5 cümləlik nəticə və istifadə olunan sintetik məlumat limitini yaz. Qeyd və nəticəni fayl, kod, cədvəl, diaqram və ya ekran görüntüsü ilə sübut et.\n6. Praktik nümunəni yerinə yetir: `raw.csv` → təmizləmə → SQL KPI → chart → nəticə cümləsi axınını README-də təsvir et. Ən azı bir düzgün və bir boş/səhv hal üçün gözlənilən nəticəni qeyd et.\n7. Əvvəlki tapşırıq şərtlərində tələb olunan faylı və linki hazırla; mənbə faylı, test nəticəsi və qısa README əlavə et.\n8. Göndərməzdən əvvəl orijinal şərtlərin hər bəndini yoxla, 3–5 cümlədə nəyi öyrəndiyini və məhdudiyyətləri izah et.\n\n## İşlənmiş praktik nümunə\n`raw.csv` → təmizləmə → SQL KPI → chart → nəticə cümləsi axınını README-də təsvir et.\nNümunəni öz layihənə uyğun dəyiş, gördüyün nəticəni nə ilə yoxladığını qeyd et. Demo rəqəmləri real statistikaya çevirmə.\n\n## Təhvil veriləcək materiallar\n- **Əsas iş:** aşağıdakı orijinal tapşırıqda tələb olunan fayl, GitHub repo və ya link.\n- **Mənbə və test:** redaktə edilə bilən fayllar, uyğun kod, sintetik data, ekran görüntüsü və ya test nəticəsi.\n- **İzah:** 3–5 cümləlik hesabat, istifadə edilmiş pulsuz alətlər və istinadlar.\n- **Təhlükəsizlik:** heç bir şifrə, API key, şəxsi müraciət məlumatı və ya icazəsiz material paylaşma.\n\n## 100 ballıq praktiki özünü qiymətləndirmə\n- **40 bal:** əsas fəaliyyətlər və rəsmi tələb olunan nəticələr hazırdır.\n- **25 bal:** nəticə işləyir, ölçülüb və mənfi hallar yoxlanıb.\n- **15 bal:** sənəd, fayl adları, README və təqdimat aydındır.\n- **10 bal:** təhlükəsizlik, mənbələr və pulsuz alət qaydalarına əməl olunub.\n- **10 bal:** seçimlərin səbəbi və növbəti təkmilləşdirmələr yazılıb.\n**Bu rubrik öyrənmə üçün nümunədir; əvvəldən qiymətləndirilmiş təqdimatları və rəsmi tapşırıq meyarlarını dəyişmir.**\n\n## Göndərməzdən əvvəl yoxla\n- Yalnız lokal, sintetik və ya istifadəsinə icazə verilmiş məlumat işlənib.\n- Paylaşım linki oxunur, fayl açılır, heç bir məxfi məlumat yoxdur.\n- Əvvəlki rəsmi şərtlərdə göstərilən nəticələr tamdır.\n\n## Əvvəlki rəsmi tapşırıq tələbləri (dəyişməyib)\n## 1. Bu tapşırıq nə üçündür?\nMəlumatdan biznes sualına cavab verən tam case study hazırlayacaqsan.\n\n## 2. Başlamazdan əvvəl\nÖz Tapşırıq 1–3 data layihən, SQL/Python və dashboard nəticələri. Analiz üçün uydurma məlumatdan istifadə edə bilərsən.\n\n## 3. Addım-addım icra\n1. Əvvəlki tapşırıqları öz repo-n və ya notebook-da davam etdir.\n2. Bir konkret biznes sualı və 2–3 yoxlanıla bilən hipotez yaz.\n3. Data quality yoxlaması və exploratory analysis apar.\n4. KPI və dashboard qur, tapıntıların datadan necə çıxdığını göstər.\n5. Məhdudiyyətləri və səbəb-nəticə iddiasının mümkün olub-olmadığını qeyd et.\n6. Nəticələri qeyri-texniki oxucu üçün qısa hesabat kimi yaz.\n\n## 4. Konkret nümunə və izah\nBiznes sualı: “Hansı ayda müraciət çoxdur və qəbul faizi necə dəyişir?” 2–3 ilkin fərziyyə yaz, sonra cədvəl və qrafiklə yoxla. Bu ara nəticələri birləşdirən layihədir; yekun təhvil 10-cu tapşırıqdır.\n\n## 5. Nə təhvil verməlisən?\nÖz GitHub repo linkin, təkrar icra edilən notebook/SQL, dashboard, əsas tapıntılar və məhdudiyyətləri göstərən case-study hesabatı. Dəstəklənməyən nəticə çıxarma.\n\n## 6. Hazır olduğunu necə yoxlamalısan?\nHər tapıntının sorğusu və ya qrafiki göstərilib. İlkin fərziyyə fakt kimi yazılmayıb; məlumatın hansı qərarı dəstəklədiyi və nəyi sübut etmədiyi izah edilib.\n\n[[EN]]\n## Beginner explanation\nThe goal is to produce **a real, verifiable outcome** rather than theory alone. **Example scenario:** Document raw data → cleaning → SQL metrics → charts → conclusions as a reproducible pipeline.\n\n## Free tools and how to start\n- **Python (free)** — https://www.python.org. Install Python locally and run scripts with fictional test fixtures.\n- **pandas (open source)** — https://pandas.pydata.org. Read fictional CSV data into a DataFrame and inspect missing/duplicate values.\n- **GitHub Free** — https://github.com. Use a free repository with README and sample code; never commit secrets or personal data.\n> No production data, paid hosting or premium subscription is required. Free quotas may change; use local tests and fictional data.\n\n## Step-by-step procedure (8 stages)\n1. Create a local `Talora / data-analytics / task-4` folder and reuse earlier fictional data or source files.\n2. Summarize the user, the problem and a verifiable success criterion in one sentence.\n3. Organize earlier analysis into data/ and notebooks/ directories. Include evidence in a file, source code, sheet, diagram or screenshot.\n4. Compute two metrics and compare them in a chart with edge-case checks. Include evidence in a file, source code, sheet, diagram or screenshot.\n5. Summarize findings and fictional-data limitations in five sentences. Include evidence in a file, source code, sheet, diagram or screenshot.\n6. Complete this worked example: Document raw data → cleaning → SQL metrics → charts → conclusions as a reproducible pipeline. Note one valid and one invalid/empty case.\n7. Prepare the deliverable required by the original instructions with editable sources, tests and a short README.\n8. Before submitting, check the original criteria and write a three-to-five sentence conclusion and limitations.\n\n## Practical worked example\nDocument raw data → cleaning → SQL metrics → charts → conclusions as a reproducible pipeline.\nAdapt the example to your own project, verify the result and do not present fictional statistics as real.\n\n## Required submission\n- **Main result:** the file, repository or link required by the unchanged original assignment below.\n- **Source and tests:** editable materials, appropriate code, fictional data, screenshots or test evidence.\n- **Explanation:** three to five sentences on findings, free tools and citations.\n- **Safety:** no passwords, API keys, private applications or unlicensed content.\n\n## Self-assessment rubric (100 points)\n- **40:** complete core actions and original deliverables.\n- **25:** measured, working result and invalid-case testing.\n- **15:** readable files, README and structure.\n- **10:** security, citations and free tools.\n- **10:** clear reasoning and suggested next steps.\n**Illustrative learning rubric only: it does not change official criteria or previously graded work.**\n\n## Before submission\n- Use local, fictional or properly authorized data.\n- Check links, exports and absence of confidential information.\n- Verify all original official requirements below.\n\n## Original official requirements (unchanged)\n## 1. Goal\nCreate a complete case study that answers a business question using data.\n\n## 2. Before you start\nYour data project from Tasks 1–3, SQL/Python, and dashboard results. Fictional data is acceptable.\n\n## 3. Step-by-step work\n1. Continue earlier work in your own repository or notebook.\n2. State one business question and two or three testable hypotheses.\n3. Check data quality and perform exploratory analysis.\n4. Build KPIs and a dashboard, showing how findings follow from the data.\n5. State limitations and whether causal claims can be justified.\n6. Write a concise report for a non-technical reader.\n\n## 4. Concrete example and explanation\nExample question: “Which month has the most applications, and how does acceptance rate vary?” Test 2–3 initial hypotheses using tables and charts. Final reproducibility handoff is Task 10.\n\n## 5. What to submit\nYour own GitHub repository link, reproducible notebook/SQL, dashboard, key findings, and case-study report with limitations. Do not make unsupported claims.\n\n## 6. How to check your work\nLink every finding to a query or chart. Do not present initial hypotheses as facts; explain supported decisions and unsupported claims."},{"slug":"data-analytics","task_number":5,"title":"Data Validation","old_description":"[[AZ]]\nMənbə datasetləri üçün schema və biznes qaydalarına əsaslanan data validation qur.\n\n[[EN]]\nValidate source datasets against a schema and explicit business rules.","old_instructions":"[[AZ]]\n## 1. Bu tapşırıq nə üçündür?\nAnalizdən əvvəl məlumatın formatını və keyfiyyətini yoxlayıb etibarlı dataset hazırlayacaqsan.\n\n## 2. Başlamazdan əvvəl\nÖz data repo-n, CSV, data types, missing value və duplicate anlayışları. Sintetik və ya açıq lisenziyalı data istifadə et.\n\n## 3. Addım-addım icra\n1. Öz data layihəni davam etdir.\n2. Ən azı 100 sətirlik CSV seç və sütunları izah edən data dictionary yaz.\n3. Missing, duplicate, invalid date və yanlış formatları yoxla.\n4. Hər problem üçün qayda müəyyən et və niyə seçdiyini yaz.\n5. Orijinal faylı saxla, təmizlənmiş faylı ayrıca yarat.\n6. Əvvəl/sonra row count və quality summary müqayisə et.\n\n## 4. Konkret nümunə və izah\nTəmizləməni avtomatik yoxlayan qaydalar əlavə et: `application_id` boş və təkrar olmasın, `created_at` tarix kimi oxunsun, `score` seçdiyin aralıqda olsun. Bu tapşırıq 1-ci tapşırığın təkrarı deyil: burada nəticənin düzgünlüyünü yoxlayan validation hesabatı qurursan.\n\n## 5. Nə təhvil verməlisən?\nÖz GitHub repo linkin, orijinal və təmiz data, data dictionary, validation qaydaları və əvvəl/sonra hesabatı. Orijinal məlumat səssizcə dəyişdirilməməlidir.\n\n## 6. Hazır olduğunu necə yoxlamalısan?\nHər qayda üçün keçən və pozan ən azı bir nümunə var. Hesabat problemli sətiri və səbəbi tapmağa imkan verir; orijinal fayl qorunur.\n\n[[EN]]\n## 1. Goal\nCheck data formats and quality before analysis and create a reliable dataset.\n\n## 2. Before you start\nYour data repository, CSV files, data types, missing values, and duplicates. Use synthetic or openly licensed data.\n\n## 3. Step-by-step work\n1. Continue your own data project.\n2. Choose a CSV with at least 100 rows and write a data dictionary.\n3. Check missing values, duplicates, invalid dates, and inconsistent formats.\n4. Define a rule for each issue and explain why you chose it.\n5. Preserve the original file and create a separate cleaned version.\n6. Compare row counts and quality summaries before/after.\n\n## 4. Concrete example and explanation\nAdd automatic checks: nonempty unique `application_id`, parseable `created_at`, and `score` within your defined range. Unlike Task 1’s cleaning, this task builds a validation report that checks the result.\n\n## 5. What to submit\nYour own GitHub repository link, original and cleaned data, data dictionary, validation rules, and before/after report. Never silently overwrite the original data.\n\n## 6. How to check your work\nProvide at least one passing and failing example per rule. The report identifies problematic rows and reasons; keep the original file.","new_description":"[[AZ]]\nMənbə datasetləri üçün schema və biznes qaydalarına əsaslanan data validation qur.\n\nPulsuz alətlər: Python (free), pandas (open source), Google Sheets (personal). Geniş bələdçi tapşırığın içindədir.\n\n[[EN]]\nValidate source datasets against a schema and explicit business rules.\n\nFree tools: Python (free), pandas (open source), Google Sheets (personal). Find the detailed walkthrough inside the task.","new_instructions":"[[AZ]]\n## Tapşırığın sadə dildə izahı\nMəqsəd bu tapşırığı özün başa düşüb **praktiki işləyən nəticə** hazırlamaqdır. **Nümunə situasiya:** `age` boş və `status='unknown'` olan sintetik sətrlər üçün validation qaydaları qur.\n\n## Pulsuz proqramlar və onlardan istifadə\n- **Python (free)** — https://www.python.org. Lokal Python qur, `.py` skriptləri və sintetik testləri terminaldan işlət.\n- **pandas (open source)** — https://pandas.pydata.org. Sintetik CSV-ni DataFrame kimi oxu, boş/dublikat dəyərləri ölç və təmizlə.\n- **Google Sheets (personal)** — https://sheets.google.com. Sütun başlıqları, sintetik sətirlər və yoxlanıla bilən hesablamalar yarat.\n> Real istehsal məlumatı, ödənişli hosting və premium abunə tələb olunmur. Pulsuz limitlər dəyişə bilər; lokal test və sintetik məlumatdan istifadə et.\n\n## Addım-addım işləmə qaydası (8 mərhələ)\n1. Yalnız öz kompüterində `Talora / data-analytics / task-5` qovluğu aç; əvvəlki tapşırıqdakı sintetik məlumat və kodu götür.\n2. Bu işdə hansı problemi həll etdiyini, istifadəçini və yoxlanacaq nəticəni bir cümlə ilə yaz.\n3. Hər sütunun tipi, icazəli dəyərləri və boş ola bilməsini data dictionary-də yaz. Qeyd və nəticəni fayl, kod, cədvəl, diaqram və ya ekran görüntüsü ilə sübut et.\n4. Yanlış tarix, mənfi say və naməlum statusu aşkarlayan üç test hazırla. Qeyd və nəticəni fayl, kod, cədvəl, diaqram və ya ekran görüntüsü ilə sübut et.\n5. Hər xəta üçün düzəltmə və ya imtina qərarını əsaslandır. Qeyd və nəticəni fayl, kod, cədvəl, diaqram və ya ekran görüntüsü ilə sübut et.\n6. Praktik nümunəni yerinə yetir: `age` boş və `status='unknown'` olan sintetik sətrlər üçün validation qaydaları qur. Ən azı bir düzgün və bir boş/səhv hal üçün gözlənilən nəticəni qeyd et.\n7. Əvvəlki tapşırıq şərtlərində tələb olunan faylı və linki hazırla; mənbə faylı, test nəticəsi və qısa README əlavə et.\n8. Göndərməzdən əvvəl orijinal şərtlərin hər bəndini yoxla, 3–5 cümlədə nəyi öyrəndiyini və məhdudiyyətləri izah et.\n\n## İşlənmiş praktik nümunə\n`age` boş və `status='unknown'` olan sintetik sətrlər üçün validation qaydaları qur.\nNümunəni öz layihənə uyğun dəyiş, gördüyün nəticəni nə ilə yoxladığını qeyd et. Demo rəqəmləri real statistikaya çevirmə.\n\n## Təhvil veriləcək materiallar\n- **Əsas iş:** aşağıdakı orijinal tapşırıqda tələb olunan fayl, GitHub repo və ya link.\n- **Mənbə və test:** redaktə edilə bilən fayllar, uyğun kod, sintetik data, ekran görüntüsü və ya test nəticəsi.\n- **İzah:** 3–5 cümləlik hesabat, istifadə edilmiş pulsuz alətlər və istinadlar.\n- **Təhlükəsizlik:** heç bir şifrə, API key, şəxsi müraciət məlumatı və ya icazəsiz material paylaşma.\n\n## 100 ballıq praktiki özünü qiymətləndirmə\n- **40 bal:** əsas fəaliyyətlər və rəsmi tələb olunan nəticələr hazırdır.\n- **25 bal:** nəticə işləyir, ölçülüb və mənfi hallar yoxlanıb.\n- **15 bal:** sənəd, fayl adları, README və təqdimat aydındır.\n- **10 bal:** təhlükəsizlik, mənbələr və pulsuz alət qaydalarına əməl olunub.\n- **10 bal:** seçimlərin səbəbi və növbəti təkmilləşdirmələr yazılıb.\n**Bu rubrik öyrənmə üçün nümunədir; əvvəldən qiymətləndirilmiş təqdimatları və rəsmi tapşırıq meyarlarını dəyişmir.**\n\n## Göndərməzdən əvvəl yoxla\n- Yalnız lokal, sintetik və ya istifadəsinə icazə verilmiş məlumat işlənib.\n- Paylaşım linki oxunur, fayl açılır, heç bir məxfi məlumat yoxdur.\n- Əvvəlki rəsmi şərtlərdə göstərilən nəticələr tamdır.\n\n## Əvvəlki rəsmi tapşırıq tələbləri (dəyişməyib)\n## 1. Bu tapşırıq nə üçündür?\nAnalizdən əvvəl məlumatın formatını və keyfiyyətini yoxlayıb etibarlı dataset hazırlayacaqsan.\n\n## 2. Başlamazdan əvvəl\nÖz data repo-n, CSV, data types, missing value və duplicate anlayışları. Sintetik və ya açıq lisenziyalı data istifadə et.\n\n## 3. Addım-addım icra\n1. Öz data layihəni davam etdir.\n2. Ən azı 100 sətirlik CSV seç və sütunları izah edən data dictionary yaz.\n3. Missing, duplicate, invalid date və yanlış formatları yoxla.\n4. Hər problem üçün qayda müəyyən et və niyə seçdiyini yaz.\n5. Orijinal faylı saxla, təmizlənmiş faylı ayrıca yarat.\n6. Əvvəl/sonra row count və quality summary müqayisə et.\n\n## 4. Konkret nümunə və izah\nTəmizləməni avtomatik yoxlayan qaydalar əlavə et: `application_id` boş və təkrar olmasın, `created_at` tarix kimi oxunsun, `score` seçdiyin aralıqda olsun. Bu tapşırıq 1-ci tapşırığın təkrarı deyil: burada nəticənin düzgünlüyünü yoxlayan validation hesabatı qurursan.\n\n## 5. Nə təhvil verməlisən?\nÖz GitHub repo linkin, orijinal və təmiz data, data dictionary, validation qaydaları və əvvəl/sonra hesabatı. Orijinal məlumat səssizcə dəyişdirilməməlidir.\n\n## 6. Hazır olduğunu necə yoxlamalısan?\nHər qayda üçün keçən və pozan ən azı bir nümunə var. Hesabat problemli sətiri və səbəbi tapmağa imkan verir; orijinal fayl qorunur.\n\n[[EN]]\n## Beginner explanation\nThe goal is to produce **a real, verifiable outcome** rather than theory alone. **Example scenario:** Add missing-value and category validation rules to a fictional dataset.\n\n## Free tools and how to start\n- **Python (free)** — https://www.python.org. Install Python locally and run scripts with fictional test fixtures.\n- **pandas (open source)** — https://pandas.pydata.org. Read fictional CSV data into a DataFrame and inspect missing/duplicate values.\n- **Google Sheets (personal)** — https://sheets.google.com. Create labeled columns, fictional sample records and verifiable calculations.\n> No production data, paid hosting or premium subscription is required. Free quotas may change; use local tests and fictional data.\n\n## Step-by-step procedure (8 stages)\n1. Create a local `Talora / data-analytics / task-5` folder and reuse earlier fictional data or source files.\n2. Summarize the user, the problem and a verifiable success criterion in one sentence.\n3. Define type, allowed values and nullability for each field. Include evidence in a file, source code, sheet, diagram or screenshot.\n4. Test invalid dates, negative counts and unknown statuses. Include evidence in a file, source code, sheet, diagram or screenshot.\n5. Explain whether each failure should be corrected or rejected. Include evidence in a file, source code, sheet, diagram or screenshot.\n6. Complete this worked example: Add missing-value and category validation rules to a fictional dataset. Note one valid and one invalid/empty case.\n7. Prepare the deliverable required by the original instructions with editable sources, tests and a short README.\n8. Before submitting, check the original criteria and write a three-to-five sentence conclusion and limitations.\n\n## Practical worked example\nAdd missing-value and category validation rules to a fictional dataset.\nAdapt the example to your own project, verify the result and do not present fictional statistics as real.\n\n## Required submission\n- **Main result:** the file, repository or link required by the unchanged original assignment below.\n- **Source and tests:** editable materials, appropriate code, fictional data, screenshots or test evidence.\n- **Explanation:** three to five sentences on findings, free tools and citations.\n- **Safety:** no passwords, API keys, private applications or unlicensed content.\n\n## Self-assessment rubric (100 points)\n- **40:** complete core actions and original deliverables.\n- **25:** measured, working result and invalid-case testing.\n- **15:** readable files, README and structure.\n- **10:** security, citations and free tools.\n- **10:** clear reasoning and suggested next steps.\n**Illustrative learning rubric only: it does not change official criteria or previously graded work.**\n\n## Before submission\n- Use local, fictional or properly authorized data.\n- Check links, exports and absence of confidential information.\n- Verify all original official requirements below.\n\n## Original official requirements (unchanged)\n## 1. Goal\nCheck data formats and quality before analysis and create a reliable dataset.\n\n## 2. Before you start\nYour data repository, CSV files, data types, missing values, and duplicates. Use synthetic or openly licensed data.\n\n## 3. Step-by-step work\n1. Continue your own data project.\n2. Choose a CSV with at least 100 rows and write a data dictionary.\n3. Check missing values, duplicates, invalid dates, and inconsistent formats.\n4. Define a rule for each issue and explain why you chose it.\n5. Preserve the original file and create a separate cleaned version.\n6. Compare row counts and quality summaries before/after.\n\n## 4. Concrete example and explanation\nAdd automatic checks: nonempty unique `application_id`, parseable `created_at`, and `score` within your defined range. Unlike Task 1’s cleaning, this task builds a validation report that checks the result.\n\n## 5. What to submit\nYour own GitHub repository link, original and cleaned data, data dictionary, validation rules, and before/after report. Never silently overwrite the original data.\n\n## 6. How to check your work\nProvide at least one passing and failing example per rule. The report identifies problematic rows and reasons; keep the original file."},{"slug":"data-analytics","task_number":6,"title":"Exploratory Analysis","old_description":"[[AZ]]\nMüraciət datasetində paylanma, kənar dəyər və istiqamətlərarası fərqləri araşdır.\n\n[[EN]]\nExplore distributions, outliers, and differences between internship tracks.","old_instructions":"[[AZ]]\n## 1. Bu tapşırıq nə üçündür?\nDataset-in əsas paylanmalarını və qeyri-adi dəyərlərini araşdırıb yoxlanıla bilən insight-lar tapacaqsan.\n\n## 2. Başlamazdan əvvəl\nÖz təmiz data faylın, Python/pandas və ya spreadsheet, orta/median və chart əsasları.\n\n## 3. Addım-addım icra\n1. Öz data repo-nu davam etdir.\n2. Əsas sütunlar üçün summary statistics hesabla.\n3. Kateqoriyalar və zaman üzrə paylanmanı qrafiklə göstər.\n4. Outlier və missing value-ları araşdır; onları avtomatik silmə.\n5. Ən azı 3 tapıntı yaz və hər birini cədvəl/qrafiklə əsaslandır.\n6. Hər tapıntının məhdudiyyətini qeyd et.\n\n## 4. Konkret nümunə və izah\nTəsviri statistika üçün say, minimum, maksimum, orta və medianı hesabla. Median sıralanmış dəyərlərin ortadakı dəyəridir. Kəskin yüksək nəticə tapanda onu silməzdən əvvəl səhv, yoxsa mümkün real fərq olduğunu araşdır.\n\n## 5. Nə təhvil verməlisən?\nÖz GitHub repo linkin, təkrar icra edilən notebook/script, ən azı 3 vizual, tapıntı izahları və məhdudiyyətlər. Qrafiklər düzgün etiketlənməlidir.\n\n## 6. Hazır olduğunu necə yoxlamalısan?\nƏn azı 3 etiketli vizual və hərəsinə bağlı tapıntı var. Anormal dəyərləri saxlamaq/silmək qərarı əsaslandırılıb; notebook və ya cədvəl yenidən hesablana bilir.\n\n[[EN]]\n## 1. Goal\nExplore distributions and unusual values in a dataset to find verifiable insights.\n\n## 2. Before you start\nYour cleaned data, Python/pandas or a spreadsheet, summary statistics, and basic charts.\n\n## 3. Step-by-step work\n1. Continue your own data repository.\n2. Calculate summary statistics for key columns.\n3. Visualize distributions by category and over time.\n4. Investigate outliers and missing values; do not automatically delete them.\n5. Write at least three findings and support each with a table/chart.\n6. State limitations for each finding.\n\n## 4. Concrete example and explanation\nCalculate count, minimum, maximum, mean, and median. The median is the middle value in sorted data. Investigate unusually large values before deciding whether they are errors.\n\n## 5. What to submit\nYour own GitHub repository link, reproducible notebook/script, at least three visuals, findings, and limitations. Charts must be clearly labelled.\n\n## 6. How to check your work\nInclude at least three labelled visuals with findings. Justify outlier decisions and make the notebook or spreadsheet reproducible.","new_description":"[[AZ]]\nMüraciət datasetində paylanma, kənar dəyər və istiqamətlərarası fərqləri araşdır.\n\nPulsuz alətlər: Python (free), pandas (open source), Matplotlib (open source). Geniş bələdçi tapşırığın içindədir.\n\n[[EN]]\nExplore distributions, outliers, and differences between internship tracks.\n\nFree tools: Python (free), pandas (open source), Matplotlib (open source). Find the detailed walkthrough inside the task.","new_instructions":"[[AZ]]\n## Tapşırığın sadə dildə izahı\nMəqsəd bu tapşırığı özün başa düşüb **praktiki işləyən nəticə** hazırlamaqdır. **Nümunə situasiya:** 30 sintetik qeyddə median müraciət yaşı, kateqoriya payı və outlier-ləri araşdır.\n\n## Pulsuz proqramlar və onlardan istifadə\n- **Python (free)** — https://www.python.org. Lokal Python qur, `.py` skriptləri və sintetik testləri terminaldan işlət.\n- **pandas (open source)** — https://pandas.pydata.org. Sintetik CSV-ni DataFrame kimi oxu, boş/dublikat dəyərləri ölç və təmizlə.\n- **Matplotlib (open source)** — https://matplotlib.org. Sintetik datadan qrafik çək, ox adlarını və vahidi qeyd et.\n> Real istehsal məlumatı, ödənişli hosting və premium abunə tələb olunmur. Pulsuz limitlər dəyişə bilər; lokal test və sintetik məlumatdan istifadə et.\n\n## Addım-addım işləmə qaydası (8 mərhələ)\n1. Yalnız öz kompüterində `Talora / data-analytics / task-6` qovluğu aç; əvvəlki tapşırıqdakı sintetik məlumat və kodu götür.\n2. Bu işdə hansı problemi həll etdiyini, istifadəçini və yoxlanacaq nəticəni bir cümlə ilə yaz.\n3. Describe, median və value_counts nəticələrini ayrıca yaz. Qeyd və nəticəni fayl, kod, cədvəl, diaqram və ya ekran görüntüsü ilə sübut et.\n4. Histogram və boxplot ilə paylanmanı müqayisə et. Qeyd və nəticəni fayl, kod, cədvəl, diaqram və ya ekran görüntüsü ilə sübut et.\n5. Görünən fərqi fakt, səbəb izahını isə fərziyyə kimi ayır. Qeyd və nəticəni fayl, kod, cədvəl, diaqram və ya ekran görüntüsü ilə sübut et.\n6. Praktik nümunəni yerinə yetir: 30 sintetik qeyddə median müraciət yaşı, kateqoriya payı və outlier-ləri araşdır. Ən azı bir düzgün və bir boş/səhv hal üçün gözlənilən nəticəni qeyd et.\n7. Əvvəlki tapşırıq şərtlərində tələb olunan faylı və linki hazırla; mənbə faylı, test nəticəsi və qısa README əlavə et.\n8. Göndərməzdən əvvəl orijinal şərtlərin hər bəndini yoxla, 3–5 cümlədə nəyi öyrəndiyini və məhdudiyyətləri izah et.\n\n## İşlənmiş praktik nümunə\n30 sintetik qeyddə median müraciət yaşı, kateqoriya payı və outlier-ləri araşdır.\nNümunəni öz layihənə uyğun dəyiş, gördüyün nəticəni nə ilə yoxladığını qeyd et. Demo rəqəmləri real statistikaya çevirmə.\n\n## Təhvil veriləcək materiallar\n- **Əsas iş:** aşağıdakı orijinal tapşırıqda tələb olunan fayl, GitHub repo və ya link.\n- **Mənbə və test:** redaktə edilə bilən fayllar, uyğun kod, sintetik data, ekran görüntüsü və ya test nəticəsi.\n- **İzah:** 3–5 cümləlik hesabat, istifadə edilmiş pulsuz alətlər və istinadlar.\n- **Təhlükəsizlik:** heç bir şifrə, API key, şəxsi müraciət məlumatı və ya icazəsiz material paylaşma.\n\n## 100 ballıq praktiki özünü qiymətləndirmə\n- **40 bal:** əsas fəaliyyətlər və rəsmi tələb olunan nəticələr hazırdır.\n- **25 bal:** nəticə işləyir, ölçülüb və mənfi hallar yoxlanıb.\n- **15 bal:** sənəd, fayl adları, README və təqdimat aydındır.\n- **10 bal:** təhlükəsizlik, mənbələr və pulsuz alət qaydalarına əməl olunub.\n- **10 bal:** seçimlərin səbəbi və növbəti təkmilləşdirmələr yazılıb.\n**Bu rubrik öyrənmə üçün nümunədir; əvvəldən qiymətləndirilmiş təqdimatları və rəsmi tapşırıq meyarlarını dəyişmir.**\n\n## Göndərməzdən əvvəl yoxla\n- Yalnız lokal, sintetik və ya istifadəsinə icazə verilmiş məlumat işlənib.\n- Paylaşım linki oxunur, fayl açılır, heç bir məxfi məlumat yoxdur.\n- Əvvəlki rəsmi şərtlərdə göstərilən nəticələr tamdır.\n\n## Əvvəlki rəsmi tapşırıq tələbləri (dəyişməyib)\n## 1. Bu tapşırıq nə üçündür?\nDataset-in əsas paylanmalarını və qeyri-adi dəyərlərini araşdırıb yoxlanıla bilən insight-lar tapacaqsan.\n\n## 2. Başlamazdan əvvəl\nÖz təmiz data faylın, Python/pandas və ya spreadsheet, orta/median və chart əsasları.\n\n## 3. Addım-addım icra\n1. Öz data repo-nu davam etdir.\n2. Əsas sütunlar üçün summary statistics hesabla.\n3. Kateqoriyalar və zaman üzrə paylanmanı qrafiklə göstər.\n4. Outlier və missing value-ları araşdır; onları avtomatik silmə.\n5. Ən azı 3 tapıntı yaz və hər birini cədvəl/qrafiklə əsaslandır.\n6. Hər tapıntının məhdudiyyətini qeyd et.\n\n## 4. Konkret nümunə və izah\nTəsviri statistika üçün say, minimum, maksimum, orta və medianı hesabla. Median sıralanmış dəyərlərin ortadakı dəyəridir. Kəskin yüksək nəticə tapanda onu silməzdən əvvəl səhv, yoxsa mümkün real fərq olduğunu araşdır.\n\n## 5. Nə təhvil verməlisən?\nÖz GitHub repo linkin, təkrar icra edilən notebook/script, ən azı 3 vizual, tapıntı izahları və məhdudiyyətlər. Qrafiklər düzgün etiketlənməlidir.\n\n## 6. Hazır olduğunu necə yoxlamalısan?\nƏn azı 3 etiketli vizual və hərəsinə bağlı tapıntı var. Anormal dəyərləri saxlamaq/silmək qərarı əsaslandırılıb; notebook və ya cədvəl yenidən hesablana bilir.\n\n[[EN]]\n## Beginner explanation\nThe goal is to produce **a real, verifiable outcome** rather than theory alone. **Example scenario:** Explore medians, category proportions and outliers from thirty synthetic records.\n\n## Free tools and how to start\n- **Python (free)** — https://www.python.org. Install Python locally and run scripts with fictional test fixtures.\n- **pandas (open source)** — https://pandas.pydata.org. Read fictional CSV data into a DataFrame and inspect missing/duplicate values.\n- **Matplotlib (open source)** — https://matplotlib.org. Chart fictional data with meaningful axis labels and units.\n> No production data, paid hosting or premium subscription is required. Free quotas may change; use local tests and fictional data.\n\n## Step-by-step procedure (8 stages)\n1. Create a local `Talora / data-analytics / task-6` folder and reuse earlier fictional data or source files.\n2. Summarize the user, the problem and a verifiable success criterion in one sentence.\n3. Compute descriptive summaries, median and category counts. Include evidence in a file, source code, sheet, diagram or screenshot.\n4. Plot a histogram and boxplot to inspect distributions. Include evidence in a file, source code, sheet, diagram or screenshot.\n5. Distinguish observed patterns from unverified causal explanations. Include evidence in a file, source code, sheet, diagram or screenshot.\n6. Complete this worked example: Explore medians, category proportions and outliers from thirty synthetic records. Note one valid and one invalid/empty case.\n7. Prepare the deliverable required by the original instructions with editable sources, tests and a short README.\n8. Before submitting, check the original criteria and write a three-to-five sentence conclusion and limitations.\n\n## Practical worked example\nExplore medians, category proportions and outliers from thirty synthetic records.\nAdapt the example to your own project, verify the result and do not present fictional statistics as real.\n\n## Required submission\n- **Main result:** the file, repository or link required by the unchanged original assignment below.\n- **Source and tests:** editable materials, appropriate code, fictional data, screenshots or test evidence.\n- **Explanation:** three to five sentences on findings, free tools and citations.\n- **Safety:** no passwords, API keys, private applications or unlicensed content.\n\n## Self-assessment rubric (100 points)\n- **40:** complete core actions and original deliverables.\n- **25:** measured, working result and invalid-case testing.\n- **15:** readable files, README and structure.\n- **10:** security, citations and free tools.\n- **10:** clear reasoning and suggested next steps.\n**Illustrative learning rubric only: it does not change official criteria or previously graded work.**\n\n## Before submission\n- Use local, fictional or properly authorized data.\n- Check links, exports and absence of confidential information.\n- Verify all original official requirements below.\n\n## Original official requirements (unchanged)\n## 1. Goal\nExplore distributions and unusual values in a dataset to find verifiable insights.\n\n## 2. Before you start\nYour cleaned data, Python/pandas or a spreadsheet, summary statistics, and basic charts.\n\n## 3. Step-by-step work\n1. Continue your own data repository.\n2. Calculate summary statistics for key columns.\n3. Visualize distributions by category and over time.\n4. Investigate outliers and missing values; do not automatically delete them.\n5. Write at least three findings and support each with a table/chart.\n6. State limitations for each finding.\n\n## 4. Concrete example and explanation\nCalculate count, minimum, maximum, mean, and median. The median is the middle value in sorted data. Investigate unusually large values before deciding whether they are errors.\n\n## 5. What to submit\nYour own GitHub repository link, reproducible notebook/script, at least three visuals, findings, and limitations. Charts must be clearly labelled.\n\n## 6. How to check your work\nInclude at least three labelled visuals with findings. Justify outlier decisions and make the notebook or spreadsheet reproducible."},{"slug":"data-analytics","task_number":7,"title":"Cohort Analysis","old_description":"[[AZ]]\nQəbul cohort-larının zamanla aktiv qalma və tapşırıq tamamlama fərqini hesabla.\n\n[[EN]]\nCompare retention and task completion over time across enrollment cohorts.","old_instructions":"[[AZ]]\n## 1. Bu tapşırıq nə üçündür?\nİstifadəçi qruplarının zamanla necə dəyişdiyini müqayisə edəcəksən.\n\n## 2. Başlamazdan əvvəl\nÖz data repo-n, tarix sahələri, qruplaşdırma və faiz hesablamaları. Cohort tərifini əvvəlcədən müəyyən et.\n\n## 3. Addım-addım icra\n1. Öz data layihəni davam etdir.\n2. Cohort-u necə müəyyən etdiyini yaz, məsələn, ilk aktivlik ayı.\n3. Hər cohort üçün sonrakı dövrlərdə aktivlik/retention göstəricisi hesabla.\n4. Kiçik sample və çatışmayan tarixlərin təsirini yoxla.\n5. Cohort cədvəli və ən azı bir heatmap/line chart hazırla.\n6. Nəticəni ehtiyatla izah et; müşahidə olunan fərqi səbəb kimi təqdim etmə.\n\n## 4. Konkret nümunə və izah\nCohort eyni ayda ilk dəfə aktiv olmuş istifadəçilər qrupudur. Yanvarda başlayan 20 nəfərdən 8-i fevralda aktivdirsə, 1-ci ayın retention-u 8/20=40%-dir. Hələ fevral müşahidəsi olmayan qrupu sıfır aktivlik kimi göstərmə.\n\n## 5. Nə təhvil verməlisən?\nÖz GitHub repo linkin, cohort SQL/notebook, nəticə cədvəli, vizual və metod izahı. Cohort tərifi və denominator aydın göstərilməlidir.\n\n## 6. Hazır olduğunu necə yoxlamalısan?\nİlk aktivlik qaydası, unikal istifadəçi sayları və faiz məxrəci aydındır. Müşahidə edilməmiş dövrlər ayrıdır; eyni istifadəçi təkrar sayılmır.\n\n[[EN]]\n## 1. Goal\nCompare how groups of users change over time.\n\n## 2. Before you start\nYour data repository, date fields, grouping, and percentage calculations. Define the cohort before analysing.\n\n## 3. Step-by-step work\n1. Continue your own data project.\n2. Define the cohort, such as the month of first activity.\n3. Calculate later activity/retention for each cohort.\n4. Check the effect of small samples and missing dates.\n5. Create a cohort table and at least one heatmap/line chart.\n6. Interpret results carefully; do not claim observed differences prove causation.\n\n## 4. Concrete example and explanation\nA cohort groups users first active in the same month. If eight of twenty January starters are active in February, month-1 retention is 40%. Do not turn unobserved future periods into zero retention.\n\n## 5. What to submit\nYour own GitHub repository link, cohort SQL/notebook, results table, visualization, and method explanation. Clearly define the cohort and denominator.\n\n## 6. How to check your work\nDefine first activity, unique-user counts, and denominators. Mark unobserved periods separately and deduplicate users.","new_description":"[[AZ]]\nQəbul cohort-larının zamanla aktiv qalma və tapşırıq tamamlama fərqini hesabla.\n\nPulsuz alətlər: Python (free), Google Sheets (personal). Geniş bələdçi tapşırığın içindədir.\n\n[[EN]]\nCompare retention and task completion over time across enrollment cohorts.\n\nFree tools: Python (free), Google Sheets (personal). Find the detailed walkthrough inside the task.","new_instructions":"[[AZ]]\n## Tapşırığın sadə dildə izahı\nMəqsəd bu tapşırığı özün başa düşüb **praktiki işləyən nəticə** hazırlamaqdır. **Nümunə situasiya:** Yanvar və fevralda qəbul olan iki sintetik cohort-un 4 həftəlik tamamlanma faizlərini müqayisə et.\n\n## Pulsuz proqramlar və onlardan istifadə\n- **Python (free)** — https://www.python.org. Lokal Python qur, `.py` skriptləri və sintetik testləri terminaldan işlət.\n- **Google Sheets (personal)** — https://sheets.google.com. Sütun başlıqları, sintetik sətirlər və yoxlanıla bilən hesablamalar yarat.\n> Real istehsal məlumatı, ödənişli hosting və premium abunə tələb olunmur. Pulsuz limitlər dəyişə bilər; lokal test və sintetik məlumatdan istifadə et.\n\n## Addım-addım işləmə qaydası (8 mərhələ)\n1. Yalnız öz kompüterində `Talora / data-analytics / task-7` qovluğu aç; əvvəlki tapşırıqdakı sintetik məlumat və kodu götür.\n2. Bu işdə hansı problemi həll etdiyini, istifadəçini və yoxlanacaq nəticəni bir cümlə ilə yaz.\n3. Cohort-u qeydiyyat ayı kimi dəqiq tərif et. Qeyd və nəticəni fayl, kod, cədvəl, diaqram və ya ekran görüntüsü ilə sübut et.\n4. Hər cohort-un 1–4-cü həftə aktiv sayını və faizini cədvəldə göstər. Qeyd və nəticəni fayl, kod, cədvəl, diaqram və ya ekran görüntüsü ilə sübut et.\n5. Kiçik nümunə və boş cohort hallarında nəticənin məhdudluğunu izah et. Qeyd və nəticəni fayl, kod, cədvəl, diaqram və ya ekran görüntüsü ilə sübut et.\n6. Praktik nümunəni yerinə yetir: Yanvar və fevralda qəbul olan iki sintetik cohort-un 4 həftəlik tamamlanma faizlərini müqayisə et. Ən azı bir düzgün və bir boş/səhv hal üçün gözlənilən nəticəni qeyd et.\n7. Əvvəlki tapşırıq şərtlərində tələb olunan faylı və linki hazırla; mənbə faylı, test nəticəsi və qısa README əlavə et.\n8. Göndərməzdən əvvəl orijinal şərtlərin hər bəndini yoxla, 3–5 cümlədə nəyi öyrəndiyini və məhdudiyyətləri izah et.\n\n## İşlənmiş praktik nümunə\nYanvar və fevralda qəbul olan iki sintetik cohort-un 4 həftəlik tamamlanma faizlərini müqayisə et.\nNümunəni öz layihənə uyğun dəyiş, gördüyün nəticəni nə ilə yoxladığını qeyd et. Demo rəqəmləri real statistikaya çevirmə.\n\n## Təhvil veriləcək materiallar\n- **Əsas iş:** aşağıdakı orijinal tapşırıqda tələb olunan fayl, GitHub repo və ya link.\n- **Mənbə və test:** redaktə edilə bilən fayllar, uyğun kod, sintetik data, ekran görüntüsü və ya test nəticəsi.\n- **İzah:** 3–5 cümləlik hesabat, istifadə edilmiş pulsuz alətlər və istinadlar.\n- **Təhlükəsizlik:** heç bir şifrə, API key, şəxsi müraciət məlumatı və ya icazəsiz material paylaşma.\n\n## 100 ballıq praktiki özünü qiymətləndirmə\n- **40 bal:** əsas fəaliyyətlər və rəsmi tələb olunan nəticələr hazırdır.\n- **25 bal:** nəticə işləyir, ölçülüb və mənfi hallar yoxlanıb.\n- **15 bal:** sənəd, fayl adları, README və təqdimat aydındır.\n- **10 bal:** təhlükəsizlik, mənbələr və pulsuz alət qaydalarına əməl olunub.\n- **10 bal:** seçimlərin səbəbi və növbəti təkmilləşdirmələr yazılıb.\n**Bu rubrik öyrənmə üçün nümunədir; əvvəldən qiymətləndirilmiş təqdimatları və rəsmi tapşırıq meyarlarını dəyişmir.**\n\n## Göndərməzdən əvvəl yoxla\n- Yalnız lokal, sintetik və ya istifadəsinə icazə verilmiş məlumat işlənib.\n- Paylaşım linki oxunur, fayl açılır, heç bir məxfi məlumat yoxdur.\n- Əvvəlki rəsmi şərtlərdə göstərilən nəticələr tamdır.\n\n## Əvvəlki rəsmi tapşırıq tələbləri (dəyişməyib)\n## 1. Bu tapşırıq nə üçündür?\nİstifadəçi qruplarının zamanla necə dəyişdiyini müqayisə edəcəksən.\n\n## 2. Başlamazdan əvvəl\nÖz data repo-n, tarix sahələri, qruplaşdırma və faiz hesablamaları. Cohort tərifini əvvəlcədən müəyyən et.\n\n## 3. Addım-addım icra\n1. Öz data layihəni davam etdir.\n2. Cohort-u necə müəyyən etdiyini yaz, məsələn, ilk aktivlik ayı.\n3. Hər cohort üçün sonrakı dövrlərdə aktivlik/retention göstəricisi hesabla.\n4. Kiçik sample və çatışmayan tarixlərin təsirini yoxla.\n5. Cohort cədvəli və ən azı bir heatmap/line chart hazırla.\n6. Nəticəni ehtiyatla izah et; müşahidə olunan fərqi səbəb kimi təqdim etmə.\n\n## 4. Konkret nümunə və izah\nCohort eyni ayda ilk dəfə aktiv olmuş istifadəçilər qrupudur. Yanvarda başlayan 20 nəfərdən 8-i fevralda aktivdirsə, 1-ci ayın retention-u 8/20=40%-dir. Hələ fevral müşahidəsi olmayan qrupu sıfır aktivlik kimi göstərmə.\n\n## 5. Nə təhvil verməlisən?\nÖz GitHub repo linkin, cohort SQL/notebook, nəticə cədvəli, vizual və metod izahı. Cohort tərifi və denominator aydın göstərilməlidir.\n\n## 6. Hazır olduğunu necə yoxlamalısan?\nİlk aktivlik qaydası, unikal istifadəçi sayları və faiz məxrəci aydındır. Müşahidə edilməmiş dövrlər ayrıdır; eyni istifadəçi təkrar sayılmır.\n\n[[EN]]\n## Beginner explanation\nThe goal is to produce **a real, verifiable outcome** rather than theory alone. **Example scenario:** Compare four-week completion rates for fictional January and February enrollment cohorts.\n\n## Free tools and how to start\n- **Python (free)** — https://www.python.org. Install Python locally and run scripts with fictional test fixtures.\n- **Google Sheets (personal)** — https://sheets.google.com. Create labeled columns, fictional sample records and verifiable calculations.\n> No production data, paid hosting or premium subscription is required. Free quotas may change; use local tests and fictional data.\n\n## Step-by-step procedure (8 stages)\n1. Create a local `Talora / data-analytics / task-7` folder and reuse earlier fictional data or source files.\n2. Summarize the user, the problem and a verifiable success criterion in one sentence.\n3. Define cohorts by enrollment month. Include evidence in a file, source code, sheet, diagram or screenshot.\n4. Compute active counts and retention percentages for weeks one through four. Include evidence in a file, source code, sheet, diagram or screenshot.\n5. Discuss small-sample and empty-cohort limitations. Include evidence in a file, source code, sheet, diagram or screenshot.\n6. Complete this worked example: Compare four-week completion rates for fictional January and February enrollment cohorts. Note one valid and one invalid/empty case.\n7. Prepare the deliverable required by the original instructions with editable sources, tests and a short README.\n8. Before submitting, check the original criteria and write a three-to-five sentence conclusion and limitations.\n\n## Practical worked example\nCompare four-week completion rates for fictional January and February enrollment cohorts.\nAdapt the example to your own project, verify the result and do not present fictional statistics as real.\n\n## Required submission\n- **Main result:** the file, repository or link required by the unchanged original assignment below.\n- **Source and tests:** editable materials, appropriate code, fictional data, screenshots or test evidence.\n- **Explanation:** three to five sentences on findings, free tools and citations.\n- **Safety:** no passwords, API keys, private applications or unlicensed content.\n\n## Self-assessment rubric (100 points)\n- **40:** complete core actions and original deliverables.\n- **25:** measured, working result and invalid-case testing.\n- **15:** readable files, README and structure.\n- **10:** security, citations and free tools.\n- **10:** clear reasoning and suggested next steps.\n**Illustrative learning rubric only: it does not change official criteria or previously graded work.**\n\n## Before submission\n- Use local, fictional or properly authorized data.\n- Check links, exports and absence of confidential information.\n- Verify all original official requirements below.\n\n## Original official requirements (unchanged)\n## 1. Goal\nCompare how groups of users change over time.\n\n## 2. Before you start\nYour data repository, date fields, grouping, and percentage calculations. Define the cohort before analysing.\n\n## 3. Step-by-step work\n1. Continue your own data project.\n2. Define the cohort, such as the month of first activity.\n3. Calculate later activity/retention for each cohort.\n4. Check the effect of small samples and missing dates.\n5. Create a cohort table and at least one heatmap/line chart.\n6. Interpret results carefully; do not claim observed differences prove causation.\n\n## 4. Concrete example and explanation\nA cohort groups users first active in the same month. If eight of twenty January starters are active in February, month-1 retention is 40%. Do not turn unobserved future periods into zero retention.\n\n## 5. What to submit\nYour own GitHub repository link, cohort SQL/notebook, results table, visualization, and method explanation. Clearly define the cohort and denominator.\n\n## 6. How to check your work\nDefine first activity, unique-user counts, and denominators. Mark unobserved periods separately and deduplicate users."},{"slug":"data-analytics","task_number":8,"title":"Dashboard Review","old_description":"[[AZ]]\nMövcud dashboard-u metrik, filtr, əlçatanlıq və səhv yozulma baxımından audit et.\n\n[[EN]]\nAudit an existing dashboard for metric correctness, filters, accessibility, and misinterpretation risk.","old_instructions":"[[AZ]]\n## 1. Bu tapşırıq nə üçündür?\nDashboard-u düzgünlük, oxunaqlıq və istifadəçi ehtiyacları baxımından audit edib yaxşılaşdıracaqsan.\n\n## 2. Başlamazdan əvvəl\nÖz dashboard-un, KPI tərifləri, chart seçimi və accessibility əsasları.\n\n## 3. Addım-addım icra\n1. Öz dashboard layihəni davam etdir.\n2. Hər KPI-nın formulunu, vahidini, mənbəsini və yenilənmə tarixini yoxla.\n3. Yanlış vizual, kəsilmiş label, yanlış scale və confusing color istifadəsini axtar.\n4. Keyboard/contrast və mobil ölçülərdə oxunaqlığı yoxla.\n5. Ən azı 5 finding-i təsir və düzəlişlə qeyd et.\n6. Ən vacib 2 düzəlişi tətbiq edib əvvəl/sonra screenshot əlavə et.\n\n## 4. Konkret nümunə və izah\nTapıntını “mobil ölçüdə ay etiketləri kəsilir; müqayisə çətindir; şaquli qrafik və ya qısa etiket istifadə et” kimi yaz. Qrafikin oxunu və rəqəmlərini mənbə ilə yoxla; sadəcə rəng zövqünü səhv sayma.\n\n## 5. Nə təhvil verməlisən?\nÖz GitHub repo linkin/dashboard faylı, 5+ finding, iki düzəliş və əvvəl/sonra screenshot-lar. Rəqəmlər source data ilə uyğun olmalıdır.\n\n## 6. Hazır olduğunu necə yoxlamalısan?\n5 müşahidə üçün yer, istifadəçiyə təsir və təklif var. Ən vacib iki düzəlişdən sonra eyni ölçüdə əvvəl/sonra görüntü və rəqəm uyğunluğu yoxlanılıb.\n\n[[EN]]\n## 1. Goal\nAudit and improve a dashboard for accuracy, readability, and user needs.\n\n## 2. Before you start\nYour dashboard, KPI definitions, chart selection, and accessibility basics.\n\n## 3. Step-by-step work\n1. Continue your own dashboard project.\n2. Check each KPI's formula, unit, source, and refresh date.\n3. Look for misleading visuals, clipped labels, incorrect scales, and confusing color use.\n4. Check keyboard/contrast and readability on mobile.\n5. Record at least five findings with impact and proposed fixes.\n6. Apply the two most important fixes and add before/after screenshots.\n\n## 4. Concrete example and explanation\nExample finding: “Month labels are clipped on mobile, preventing comparison; use shorter labels or a different layout.” Verify axes and values against source data rather than treating taste as a defect.\n\n## 5. What to submit\nYour own GitHub repository/dashboard file, five or more findings, two fixes, and before/after screenshots. Values must match the source data.\n\n## 6. How to check your work\nRecord location, user impact, and recommendation for five findings. Show comparable before/after images for two fixes and recheck values.","new_description":"[[AZ]]\nMövcud dashboard-u metrik, filtr, əlçatanlıq və səhv yozulma baxımından audit et.\n\nPulsuz alətlər: Google Sheets (personal), Matplotlib (open source), Google Docs (personal). Geniş bələdçi tapşırığın içindədir.\n\n[[EN]]\nAudit an existing dashboard for metric correctness, filters, accessibility, and misinterpretation risk.\n\nFree tools: Google Sheets (personal), Matplotlib (open source), Google Docs (personal). Find the detailed walkthrough inside the task.","new_instructions":"[[AZ]]\n## Tapşırığın sadə dildə izahı\nMəqsəd bu tapşırığı özün başa düşüb **praktiki işləyən nəticə** hazırlamaqdır. **Nümunə situasiya:** Dashboard-da yanlış faiz məxrəci, oxunması çətin rəng və itən filtr halları üçün audit yaz.\n\n## Pulsuz proqramlar və onlardan istifadə\n- **Google Sheets (personal)** — https://sheets.google.com. Sütun başlıqları, sintetik sətirlər və yoxlanıla bilən hesablamalar yarat.\n- **Matplotlib (open source)** — https://matplotlib.org. Sintetik datadan qrafik çək, ox adlarını və vahidi qeyd et.\n- **Google Docs (personal)** — https://docs.google.com/document/. Boş sənəd aç, məqsəd/nəticə/cədvəl bölmələrini qur və lazım olduqda PDF ixrac et.\n> Real istehsal məlumatı, ödənişli hosting və premium abunə tələb olunmur. Pulsuz limitlər dəyişə bilər; lokal test və sintetik məlumatdan istifadə et.\n\n## Addım-addım işləmə qaydası (8 mərhələ)\n1. Yalnız öz kompüterində `Talora / data-analytics / task-8` qovluğu aç; əvvəlki tapşırıqdakı sintetik məlumat və kodu götür.\n2. Bu işdə hansı problemi həll etdiyini, istifadəçini və yoxlanacaq nəticəni bir cümlə ilə yaz.\n3. Hər vizual üçün mənbə, metrikanın düsturu və filtr təsirini yoxla. Qeyd və nəticəni fayl, kod, cədvəl, diaqram və ya ekran görüntüsü ilə sübut et.\n4. Ən azı 5 problem üçün risk, təsir və düzəliş sütunu hazırla. Qeyd və nəticəni fayl, kod, cədvəl, diaqram və ya ekran görüntüsü ilə sübut et.\n5. Bir qrafiki düzəldib əvvəl/sonra görüntüsünü təqdim et. Qeyd və nəticəni fayl, kod, cədvəl, diaqram və ya ekran görüntüsü ilə sübut et.\n6. Praktik nümunəni yerinə yetir: Dashboard-da yanlış faiz məxrəci, oxunması çətin rəng və itən filtr halları üçün audit yaz. Ən azı bir düzgün və bir boş/səhv hal üçün gözlənilən nəticəni qeyd et.\n7. Əvvəlki tapşırıq şərtlərində tələb olunan faylı və linki hazırla; mənbə faylı, test nəticəsi və qısa README əlavə et.\n8. Göndərməzdən əvvəl orijinal şərtlərin hər bəndini yoxla, 3–5 cümlədə nəyi öyrəndiyini və məhdudiyyətləri izah et.\n\n## İşlənmiş praktik nümunə\nDashboard-da yanlış faiz məxrəci, oxunması çətin rəng və itən filtr halları üçün audit yaz.\nNümunəni öz layihənə uyğun dəyiş, gördüyün nəticəni nə ilə yoxladığını qeyd et. Demo rəqəmləri real statistikaya çevirmə.\n\n## Təhvil veriləcək materiallar\n- **Əsas iş:** aşağıdakı orijinal tapşırıqda tələb olunan fayl, GitHub repo və ya link.\n- **Mənbə və test:** redaktə edilə bilən fayllar, uyğun kod, sintetik data, ekran görüntüsü və ya test nəticəsi.\n- **İzah:** 3–5 cümləlik hesabat, istifadə edilmiş pulsuz alətlər və istinadlar.\n- **Təhlükəsizlik:** heç bir şifrə, API key, şəxsi müraciət məlumatı və ya icazəsiz material paylaşma.\n\n## 100 ballıq praktiki özünü qiymətləndirmə\n- **40 bal:** əsas fəaliyyətlər və rəsmi tələb olunan nəticələr hazırdır.\n- **25 bal:** nəticə işləyir, ölçülüb və mənfi hallar yoxlanıb.\n- **15 bal:** sənəd, fayl adları, README və təqdimat aydındır.\n- **10 bal:** təhlükəsizlik, mənbələr və pulsuz alət qaydalarına əməl olunub.\n- **10 bal:** seçimlərin səbəbi və növbəti təkmilləşdirmələr yazılıb.\n**Bu rubrik öyrənmə üçün nümunədir; əvvəldən qiymətləndirilmiş təqdimatları və rəsmi tapşırıq meyarlarını dəyişmir.**\n\n## Göndərməzdən əvvəl yoxla\n- Yalnız lokal, sintetik və ya istifadəsinə icazə verilmiş məlumat işlənib.\n- Paylaşım linki oxunur, fayl açılır, heç bir məxfi məlumat yoxdur.\n- Əvvəlki rəsmi şərtlərdə göstərilən nəticələr tamdır.\n\n## Əvvəlki rəsmi tapşırıq tələbləri (dəyişməyib)\n## 1. Bu tapşırıq nə üçündür?\nDashboard-u düzgünlük, oxunaqlıq və istifadəçi ehtiyacları baxımından audit edib yaxşılaşdıracaqsan.\n\n## 2. Başlamazdan əvvəl\nÖz dashboard-un, KPI tərifləri, chart seçimi və accessibility əsasları.\n\n## 3. Addım-addım icra\n1. Öz dashboard layihəni davam etdir.\n2. Hər KPI-nın formulunu, vahidini, mənbəsini və yenilənmə tarixini yoxla.\n3. Yanlış vizual, kəsilmiş label, yanlış scale və confusing color istifadəsini axtar.\n4. Keyboard/contrast və mobil ölçülərdə oxunaqlığı yoxla.\n5. Ən azı 5 finding-i təsir və düzəlişlə qeyd et.\n6. Ən vacib 2 düzəlişi tətbiq edib əvvəl/sonra screenshot əlavə et.\n\n## 4. Konkret nümunə və izah\nTapıntını “mobil ölçüdə ay etiketləri kəsilir; müqayisə çətindir; şaquli qrafik və ya qısa etiket istifadə et” kimi yaz. Qrafikin oxunu və rəqəmlərini mənbə ilə yoxla; sadəcə rəng zövqünü səhv sayma.\n\n## 5. Nə təhvil verməlisən?\nÖz GitHub repo linkin/dashboard faylı, 5+ finding, iki düzəliş və əvvəl/sonra screenshot-lar. Rəqəmlər source data ilə uyğun olmalıdır.\n\n## 6. Hazır olduğunu necə yoxlamalısan?\n5 müşahidə üçün yer, istifadəçiyə təsir və təklif var. Ən vacib iki düzəlişdən sonra eyni ölçüdə əvvəl/sonra görüntü və rəqəm uyğunluğu yoxlanılıb.\n\n[[EN]]\n## Beginner explanation\nThe goal is to produce **a real, verifiable outcome** rather than theory alone. **Example scenario:** Audit a fictional dashboard for wrong denominators, unreadable colors and broken filters.\n\n## Free tools and how to start\n- **Google Sheets (personal)** — https://sheets.google.com. Create labeled columns, fictional sample records and verifiable calculations.\n- **Matplotlib (open source)** — https://matplotlib.org. Chart fictional data with meaningful axis labels and units.\n- **Google Docs (personal)** — https://docs.google.com/document/. Create a document with goals, evidence, tables and a PDF export when needed.\n> No production data, paid hosting or premium subscription is required. Free quotas may change; use local tests and fictional data.\n\n## Step-by-step procedure (8 stages)\n1. Create a local `Talora / data-analytics / task-8` folder and reuse earlier fictional data or source files.\n2. Summarize the user, the problem and a verifiable success criterion in one sentence.\n3. Check source data, metric formulas and filter effects for each visual. Include evidence in a file, source code, sheet, diagram or screenshot.\n4. Record five issues with risks, impact and proposed remedies. Include evidence in a file, source code, sheet, diagram or screenshot.\n5. Correct one chart and provide a before/after comparison. Include evidence in a file, source code, sheet, diagram or screenshot.\n6. Complete this worked example: Audit a fictional dashboard for wrong denominators, unreadable colors and broken filters. Note one valid and one invalid/empty case.\n7. Prepare the deliverable required by the original instructions with editable sources, tests and a short README.\n8. Before submitting, check the original criteria and write a three-to-five sentence conclusion and limitations.\n\n## Practical worked example\nAudit a fictional dashboard for wrong denominators, unreadable colors and broken filters.\nAdapt the example to your own project, verify the result and do not present fictional statistics as real.\n\n## Required submission\n- **Main result:** the file, repository or link required by the unchanged original assignment below.\n- **Source and tests:** editable materials, appropriate code, fictional data, screenshots or test evidence.\n- **Explanation:** three to five sentences on findings, free tools and citations.\n- **Safety:** no passwords, API keys, private applications or unlicensed content.\n\n## Self-assessment rubric (100 points)\n- **40:** complete core actions and original deliverables.\n- **25:** measured, working result and invalid-case testing.\n- **15:** readable files, README and structure.\n- **10:** security, citations and free tools.\n- **10:** clear reasoning and suggested next steps.\n**Illustrative learning rubric only: it does not change official criteria or previously graded work.**\n\n## Before submission\n- Use local, fictional or properly authorized data.\n- Check links, exports and absence of confidential information.\n- Verify all original official requirements below.\n\n## Original official requirements (unchanged)\n## 1. Goal\nAudit and improve a dashboard for accuracy, readability, and user needs.\n\n## 2. Before you start\nYour dashboard, KPI definitions, chart selection, and accessibility basics.\n\n## 3. Step-by-step work\n1. Continue your own dashboard project.\n2. Check each KPI's formula, unit, source, and refresh date.\n3. Look for misleading visuals, clipped labels, incorrect scales, and confusing color use.\n4. Check keyboard/contrast and readability on mobile.\n5. Record at least five findings with impact and proposed fixes.\n6. Apply the two most important fixes and add before/after screenshots.\n\n## 4. Concrete example and explanation\nExample finding: “Month labels are clipped on mobile, preventing comparison; use shorter labels or a different layout.” Verify axes and values against source data rather than treating taste as a defect.\n\n## 5. What to submit\nYour own GitHub repository/dashboard file, five or more findings, two fixes, and before/after screenshots. Values must match the source data.\n\n## 6. How to check your work\nRecord location, user impact, and recommendation for five findings. Show comparable before/after images for two fixes and recheck values."},{"slug":"data-analytics","task_number":9,"title":"Data Storytelling","old_description":"[[AZ]]\nAnaliz nəticəsini qeyri-texniki auditoriyaya problem–sübut–tövsiyə hekayəsi ilə çatdır.\n\n[[EN]]\nCommunicate analytical findings to a non-technical audience using a problem-evidence-recommendation narrative.","old_instructions":"[[AZ]]\n## 1. Bu tapşırıq nə üçündür?\nAnaliz nəticələrini texniki olmayan auditoriya üçün aydın hekayəyə çevirəcəksən.\n\n## 2. Başlamazdan əvvəl\nÖz analiz nəticələrin, qrafiklər və əsas tapıntılar. Səbəb-nəticə barədə sübut yoxdursa, əlaqəni səbəb kimi təqdim etmə.\n\n## 3. Addım-addım icra\n1. Öz data repo-nu davam etdir.\n2. Auditoriyanı və onların qərar ehtiyacını müəyyən et.\n3. Əsas sualı, 3 tapıntını və tövsiyəni seç.\n4. Hər tapıntı üçün data sübutu və məhdudiyyət göstər.\n5. Qısa report/slayd və ya notebook narrative hazırla.\n6. Başqa birinə oxut və anlaşılmayan terminləri sadələşdir.\n\n## 4. Konkret nümunə və izah\nHesabatı belə qur: hansı qərar verilməlidir → 3 əsas tapıntı → onları göstərən qrafiklər → tövsiyə → məhdudiyyət. “X artırdı, deməli Y-yə səbəb oldu” nəticəsi üçün təkcə yanaşı dəyişmə kifayət etmir.\n\n## 5. Nə təhvil verməlisən?\nÖz GitHub repo linkin, 1–3 səhifəlik report/slayd, vizuallar və tövsiyələr. Hər iddia konkret nəticə ilə dəstəklənməlidir.\n\n## 6. Hazır olduğunu necə yoxlamalısan?\n1–3 səhifə/slaydda əsas sual və qərar görünür. Hər rəqəm mənbəyə bağlıdır; oxucu rəyi alınıb və anlaşılmayan ən azı bir ifadə sadələşdirilib.\n\n[[EN]]\n## 1. Goal\nTurn analysis results into a clear story for a non-technical audience.\n\n## 2. Before you start\nYour analysis, charts, and main findings. Do not describe correlation as causation without evidence.\n\n## 3. Step-by-step work\n1. Continue your own data repository.\n2. Define the audience and the decision they need to make.\n3. Choose the main question, three findings, and a recommendation.\n4. Support each finding with data evidence and a limitation.\n5. Prepare a short report/slides or a narrative notebook.\n6. Ask someone to read it and simplify unclear terminology.\n\n## 4. Concrete example and explanation\nStructure the report as decision → three findings → supporting charts → recommendation → limitations. Two variables changing together does not prove causation.\n\n## 5. What to submit\nYour own GitHub repository link, a one-to-three-page report/slides, visuals, and recommendations. Every claim must be supported by a concrete result.\n\n## 6. How to check your work\nState the question and decision in 1–3 pages/slides. Trace numbers to sources and simplify at least one unclear phrase after reader feedback.","new_description":"[[AZ]]\nAnaliz nəticəsini qeyri-texniki auditoriyaya problem–sübut–tövsiyə hekayəsi ilə çatdır.\n\nPulsuz alətlər: Google Slides (personal), Google Docs (personal), Matplotlib (open source). Geniş bələdçi tapşırığın içindədir.\n\n[[EN]]\nCommunicate analytical findings to a non-technical audience using a problem-evidence-recommendation narrative.\n\nFree tools: Google Slides (personal), Google Docs (personal), Matplotlib (open source). Find the detailed walkthrough inside the task.","new_instructions":"[[AZ]]\n## Tapşırığın sadə dildə izahı\nMəqsəd bu tapşırığı özün başa düşüb **praktiki işləyən nəticə** hazırlamaqdır. **Nümunə situasiya:** 'Müraciətlər hansı həftədə azalır?' sualına 2 qrafik, 3 fakt və 1 tövsiyə ilə cavab yaz.\n\n## Pulsuz proqramlar və onlardan istifadə\n- **Google Slides (personal)** — https://slides.google.com. Bir slaydda bir fikir saxla, export PDF al və mənbələri qeyd et.\n- **Google Docs (personal)** — https://docs.google.com/document/. Boş sənəd aç, məqsəd/nəticə/cədvəl bölmələrini qur və lazım olduqda PDF ixrac et.\n- **Matplotlib (open source)** — https://matplotlib.org. Sintetik datadan qrafik çək, ox adlarını və vahidi qeyd et.\n> Real istehsal məlumatı, ödənişli hosting və premium abunə tələb olunmur. Pulsuz limitlər dəyişə bilər; lokal test və sintetik məlumatdan istifadə et.\n\n## Addım-addım işləmə qaydası (8 mərhələ)\n1. Yalnız öz kompüterində `Talora / data-analytics / task-9` qovluğu aç; əvvəlki tapşırıqdakı sintetik məlumat və kodu götür.\n2. Bu işdə hansı problemi həll etdiyini, istifadəçini və yoxlanacaq nəticəni bir cümlə ilə yaz.\n3. Oxucu auditoriyasını təyin et və bir əsas qərar sualı yaz. Qeyd və nəticəni fayl, kod, cədvəl, diaqram və ya ekran görüntüsü ilə sübut et.\n4. Qrafiklərdə ölçülən faktları eyni vahidlə izah et. Qeyd və nəticəni fayl, kod, cədvəl, diaqram və ya ekran görüntüsü ilə sübut et.\n5. Sübut olmayan səbəb iddiasını ehtimal kimi qeyd et. Qeyd və nəticəni fayl, kod, cədvəl, diaqram və ya ekran görüntüsü ilə sübut et.\n6. Praktik nümunəni yerinə yetir: 'Müraciətlər hansı həftədə azalır?' sualına 2 qrafik, 3 fakt və 1 tövsiyə ilə cavab yaz. Ən azı bir düzgün və bir boş/səhv hal üçün gözlənilən nəticəni qeyd et.\n7. Əvvəlki tapşırıq şərtlərində tələb olunan faylı və linki hazırla; mənbə faylı, test nəticəsi və qısa README əlavə et.\n8. Göndərməzdən əvvəl orijinal şərtlərin hər bəndini yoxla, 3–5 cümlədə nəyi öyrəndiyini və məhdudiyyətləri izah et.\n\n## İşlənmiş praktik nümunə\n'Müraciətlər hansı həftədə azalır?' sualına 2 qrafik, 3 fakt və 1 tövsiyə ilə cavab yaz.\nNümunəni öz layihənə uyğun dəyiş, gördüyün nəticəni nə ilə yoxladığını qeyd et. Demo rəqəmləri real statistikaya çevirmə.\n\n## Təhvil veriləcək materiallar\n- **Əsas iş:** aşağıdakı orijinal tapşırıqda tələb olunan fayl, GitHub repo və ya link.\n- **Mənbə və test:** redaktə edilə bilən fayllar, uyğun kod, sintetik data, ekran görüntüsü və ya test nəticəsi.\n- **İzah:** 3–5 cümləlik hesabat, istifadə edilmiş pulsuz alətlər və istinadlar.\n- **Təhlükəsizlik:** heç bir şifrə, API key, şəxsi müraciət məlumatı və ya icazəsiz material paylaşma.\n\n## 100 ballıq praktiki özünü qiymətləndirmə\n- **40 bal:** əsas fəaliyyətlər və rəsmi tələb olunan nəticələr hazırdır.\n- **25 bal:** nəticə işləyir, ölçülüb və mənfi hallar yoxlanıb.\n- **15 bal:** sənəd, fayl adları, README və təqdimat aydındır.\n- **10 bal:** təhlükəsizlik, mənbələr və pulsuz alət qaydalarına əməl olunub.\n- **10 bal:** seçimlərin səbəbi və növbəti təkmilləşdirmələr yazılıb.\n**Bu rubrik öyrənmə üçün nümunədir; əvvəldən qiymətləndirilmiş təqdimatları və rəsmi tapşırıq meyarlarını dəyişmir.**\n\n## Göndərməzdən əvvəl yoxla\n- Yalnız lokal, sintetik və ya istifadəsinə icazə verilmiş məlumat işlənib.\n- Paylaşım linki oxunur, fayl açılır, heç bir məxfi məlumat yoxdur.\n- Əvvəlki rəsmi şərtlərdə göstərilən nəticələr tamdır.\n\n## Əvvəlki rəsmi tapşırıq tələbləri (dəyişməyib)\n## 1. Bu tapşırıq nə üçündür?\nAnaliz nəticələrini texniki olmayan auditoriya üçün aydın hekayəyə çevirəcəksən.\n\n## 2. Başlamazdan əvvəl\nÖz analiz nəticələrin, qrafiklər və əsas tapıntılar. Səbəb-nəticə barədə sübut yoxdursa, əlaqəni səbəb kimi təqdim etmə.\n\n## 3. Addım-addım icra\n1. Öz data repo-nu davam etdir.\n2. Auditoriyanı və onların qərar ehtiyacını müəyyən et.\n3. Əsas sualı, 3 tapıntını və tövsiyəni seç.\n4. Hər tapıntı üçün data sübutu və məhdudiyyət göstər.\n5. Qısa report/slayd və ya notebook narrative hazırla.\n6. Başqa birinə oxut və anlaşılmayan terminləri sadələşdir.\n\n## 4. Konkret nümunə və izah\nHesabatı belə qur: hansı qərar verilməlidir → 3 əsas tapıntı → onları göstərən qrafiklər → tövsiyə → məhdudiyyət. “X artırdı, deməli Y-yə səbəb oldu” nəticəsi üçün təkcə yanaşı dəyişmə kifayət etmir.\n\n## 5. Nə təhvil verməlisən?\nÖz GitHub repo linkin, 1–3 səhifəlik report/slayd, vizuallar və tövsiyələr. Hər iddia konkret nəticə ilə dəstəklənməlidir.\n\n## 6. Hazır olduğunu necə yoxlamalısan?\n1–3 səhifə/slaydda əsas sual və qərar görünür. Hər rəqəm mənbəyə bağlıdır; oxucu rəyi alınıb və anlaşılmayan ən azı bir ifadə sadələşdirilib.\n\n[[EN]]\n## Beginner explanation\nThe goal is to produce **a real, verifiable outcome** rather than theory alone. **Example scenario:** Answer why applications dip using two charts, three observations and one recommendation.\n\n## Free tools and how to start\n- **Google Slides (personal)** — https://slides.google.com. Keep one idea per slide, cite sources and export to PDF.\n- **Google Docs (personal)** — https://docs.google.com/document/. Create a document with goals, evidence, tables and a PDF export when needed.\n- **Matplotlib (open source)** — https://matplotlib.org. Chart fictional data with meaningful axis labels and units.\n> No production data, paid hosting or premium subscription is required. Free quotas may change; use local tests and fictional data.\n\n## Step-by-step procedure (8 stages)\n1. Create a local `Talora / data-analytics / task-9` folder and reuse earlier fictional data or source files.\n2. Summarize the user, the problem and a verifiable success criterion in one sentence.\n3. Specify the audience and the decision question. Include evidence in a file, source code, sheet, diagram or screenshot.\n4. Explain charts using consistent units and verified calculations. Include evidence in a file, source code, sheet, diagram or screenshot.\n5. Label possible causes as hypotheses unless there is evidence. Include evidence in a file, source code, sheet, diagram or screenshot.\n6. Complete this worked example: Answer why applications dip using two charts, three observations and one recommendation. Note one valid and one invalid/empty case.\n7. Prepare the deliverable required by the original instructions with editable sources, tests and a short README.\n8. Before submitting, check the original criteria and write a three-to-five sentence conclusion and limitations.\n\n## Practical worked example\nAnswer why applications dip using two charts, three observations and one recommendation.\nAdapt the example to your own project, verify the result and do not present fictional statistics as real.\n\n## Required submission\n- **Main result:** the file, repository or link required by the unchanged original assignment below.\n- **Source and tests:** editable materials, appropriate code, fictional data, screenshots or test evidence.\n- **Explanation:** three to five sentences on findings, free tools and citations.\n- **Safety:** no passwords, API keys, private applications or unlicensed content.\n\n## Self-assessment rubric (100 points)\n- **40:** complete core actions and original deliverables.\n- **25:** measured, working result and invalid-case testing.\n- **15:** readable files, README and structure.\n- **10:** security, citations and free tools.\n- **10:** clear reasoning and suggested next steps.\n**Illustrative learning rubric only: it does not change official criteria or previously graded work.**\n\n## Before submission\n- Use local, fictional or properly authorized data.\n- Check links, exports and absence of confidential information.\n- Verify all original official requirements below.\n\n## Original official requirements (unchanged)\n## 1. Goal\nTurn analysis results into a clear story for a non-technical audience.\n\n## 2. Before you start\nYour analysis, charts, and main findings. Do not describe correlation as causation without evidence.\n\n## 3. Step-by-step work\n1. Continue your own data repository.\n2. Define the audience and the decision they need to make.\n3. Choose the main question, three findings, and a recommendation.\n4. Support each finding with data evidence and a limitation.\n5. Prepare a short report/slides or a narrative notebook.\n6. Ask someone to read it and simplify unclear terminology.\n\n## 4. Concrete example and explanation\nStructure the report as decision → three findings → supporting charts → recommendation → limitations. Two variables changing together does not prove causation.\n\n## 5. What to submit\nYour own GitHub repository link, a one-to-three-page report/slides, visuals, and recommendations. Every claim must be supported by a concrete result.\n\n## 6. How to check your work\nState the question and decision in 1–3 pages/slides. Trace numbers to sources and simplify at least one unclear phrase after reader feedback."},{"slug":"data-analytics","task_number":10,"title":"Reproducible Analysis","old_description":"[[AZ]]\nAnaliz layihəsini başqa analitikin yenidən icra edə biləcəyi şəkildə paketlə və məhdudiyyətləri sənədləşdir.\n\n[[EN]]\nPackage an analysis so another analyst can reproduce it and understand its limitations.","old_instructions":"[[AZ]]\n## 1. Bu tapşırıq nə üçündür?\nAnalizi başqa şəxsin də eyni nəticəni ala biləcəyi şəkildə təşkil edib sənədləşdirəcəksən.\n\n## 2. Başlamazdan əvvəl\nÖz Tapşırıq 1–9 data layihən, notebook/SQL, dependency və data-source sənədləşdirməsi.\n\n## 3. Addım-addım icra\n1. Əvvəlki analizləri öz repo-n və ya notebook-da davam etdir.\n2. Qovluq quruluşunu, data source-u və quraşdırma addımlarını README-də yaz.\n3. Orijinal data və transform edilmiş data fərqini saxla; şəxsi/həssas məlumatı repo-ya yükləmə.\n4. Notebook-u təmiz kernel-dən başdan sona işə sal.\n5. SQL, data cleaning, chart və nəticələrin eyni qaydada yarandığını yoxla.\n6. Məlum limitlər və növbəti 3 təkmilləşdirməni qeyd et.\n\n## 4. Konkret nümunə və izah\nTəkrar icra yoxlaması: yeni qovluğa klonla, paket versiyalarını quraşdır, notebook-un yaddaşını sıfırla və bütün xanaları ardıcıllıqla işə sal. Yalnız Excel/Sheets istifadə edirsənsə, mənbə faylı və formulların yenilənmə addımlarını göstər.\n\n## 5. Nə təhvil verməlisən?\nÖz GitHub repo linkin, təkrar icra edilən notebook/SQL, README, data dictionary, nəticə faylları və clean-run sübutu. Başqa şəxs quraşdırma addımları ilə nəticəni təkrar yarada bilməlidir.\n\n## 6. Hazır olduğunu necə yoxlamalısan?\nYeni icrada eyni sətir sayları, KPI-lar və qrafiklər alınır. Lazım olan data mənbəsi, kitabxana versiyaları və əmrlər sənədləşib.\n\n[[EN]]\n## 1. Goal\nOrganize and document the analysis so another person can reproduce the same results.\n\n## 2. Before you start\nYour data project from Tasks 1–9, notebooks/SQL, dependencies, and data-source documentation.\n\n## 3. Step-by-step work\n1. Continue earlier analysis in your own repository or notebook.\n2. Document folder structure, data source, and setup in the README.\n3. Keep original and transformed data distinct; never commit personal/sensitive data.\n4. Run the notebook from top to bottom in a clean kernel.\n5. Verify SQL, cleaning, charts, and results are reproduced consistently.\n6. Record known limitations and the next three improvements.\n\n## 4. Concrete example and explanation\nReproduce from a new folder: install recorded package versions, restart the notebook kernel, and run cells in order. For Excel/Sheets, include source data and steps to refresh formulas.\n\n## 5. What to submit\nYour own GitHub repository link, reproducible notebook/SQL, README, data dictionary, output files, and clean-run evidence. Another person must be able to reproduce the results by following the setup steps.\n\n## 6. How to check your work\nA new run reproduces row counts, KPIs, and charts. Document data sources, dependency versions, and commands.","new_description":"[[AZ]]\nAnaliz layihəsini başqa analitikin yenidən icra edə biləcəyi şəkildə paketlə və məhdudiyyətləri sənədləşdir.\n\nPulsuz alətlər: Python (free), GitHub Free, Google Docs (personal). Geniş bələdçi tapşırığın içindədir.\n\n[[EN]]\nPackage an analysis so another analyst can reproduce it and understand its limitations.\n\nFree tools: Python (free), GitHub Free, Google Docs (personal). Find the detailed walkthrough inside the task.","new_instructions":"[[AZ]]\n## Tapşırığın sadə dildə izahı\nMəqsəd bu tapşırığı özün başa düşüb **praktiki işləyən nəticə** hazırlamaqdır. **Nümunə situasiya:** Repo klonlandıqda `requirements.txt`, `clean.py` və `README.md` ilə eyni nəticə yenidən alınsın.\n\n## Pulsuz proqramlar və onlardan istifadə\n- **Python (free)** — https://www.python.org. Lokal Python qur, `.py` skriptləri və sintetik testləri terminaldan işlət.\n- **GitHub Free** — https://github.com. README və nümunə kod üçün şəxsi repo yarat; token və şəxsi data yükləmə.\n- **Google Docs (personal)** — https://docs.google.com/document/. Boş sənəd aç, məqsəd/nəticə/cədvəl bölmələrini qur və lazım olduqda PDF ixrac et.\n> Real istehsal məlumatı, ödənişli hosting və premium abunə tələb olunmur. Pulsuz limitlər dəyişə bilər; lokal test və sintetik məlumatdan istifadə et.\n\n## Addım-addım işləmə qaydası (8 mərhələ)\n1. Yalnız öz kompüterində `Talora / data-analytics / task-10` qovluğu aç; əvvəlki tapşırıqdakı sintetik məlumat və kodu götür.\n2. Bu işdə hansı problemi həll etdiyini, istifadəçini və yoxlanacaq nəticəni bir cümlə ilə yaz.\n3. Yalnız sintetik və ya icazəli dataset, versiyalı kod və requirements fayllarını saxla. Qeyd və nəticəni fayl, kod, cədvəl, diaqram və ya ekran görüntüsü ilə sübut et.\n4. Lokal sıfırdan işə salma əmrlərini README-də yaz. Qeyd və nəticəni fayl, kod, cədvəl, diaqram və ya ekran görüntüsü ilə sübut et.\n5. Nəticə CSV-si ilə qrafikin uyğunluğunu təkrar test et və limitləri qeyd et. Qeyd və nəticəni fayl, kod, cədvəl, diaqram və ya ekran görüntüsü ilə sübut et.\n6. Praktik nümunəni yerinə yetir: Repo klonlandıqda `requirements.txt`, `clean.py` və `README.md` ilə eyni nəticə yenidən alınsın. Ən azı bir düzgün və bir boş/səhv hal üçün gözlənilən nəticəni qeyd et.\n7. Əvvəlki tapşırıq şərtlərində tələb olunan faylı və linki hazırla; mənbə faylı, test nəticəsi və qısa README əlavə et.\n8. Göndərməzdən əvvəl orijinal şərtlərin hər bəndini yoxla, 3–5 cümlədə nəyi öyrəndiyini və məhdudiyyətləri izah et.\n\n## İşlənmiş praktik nümunə\nRepo klonlandıqda `requirements.txt`, `clean.py` və `README.md` ilə eyni nəticə yenidən alınsın.\nNümunəni öz layihənə uyğun dəyiş, gördüyün nəticəni nə ilə yoxladığını qeyd et. Demo rəqəmləri real statistikaya çevirmə.\n\n## Təhvil veriləcək materiallar\n- **Əsas iş:** aşağıdakı orijinal tapşırıqda tələb olunan fayl, GitHub repo və ya link.\n- **Mənbə və test:** redaktə edilə bilən fayllar, uyğun kod, sintetik data, ekran görüntüsü və ya test nəticəsi.\n- **İzah:** 3–5 cümləlik hesabat, istifadə edilmiş pulsuz alətlər və istinadlar.\n- **Təhlükəsizlik:** heç bir şifrə, API key, şəxsi müraciət məlumatı və ya icazəsiz material paylaşma.\n\n## 100 ballıq praktiki özünü qiymətləndirmə\n- **40 bal:** əsas fəaliyyətlər və rəsmi tələb olunan nəticələr hazırdır.\n- **25 bal:** nəticə işləyir, ölçülüb və mənfi hallar yoxlanıb.\n- **15 bal:** sənəd, fayl adları, README və təqdimat aydındır.\n- **10 bal:** təhlükəsizlik, mənbələr və pulsuz alət qaydalarına əməl olunub.\n- **10 bal:** seçimlərin səbəbi və növbəti təkmilləşdirmələr yazılıb.\n**Bu rubrik öyrənmə üçün nümunədir; əvvəldən qiymətləndirilmiş təqdimatları və rəsmi tapşırıq meyarlarını dəyişmir.**\n\n## Göndərməzdən əvvəl yoxla\n- Yalnız lokal, sintetik və ya istifadəsinə icazə verilmiş məlumat işlənib.\n- Paylaşım linki oxunur, fayl açılır, heç bir məxfi məlumat yoxdur.\n- Əvvəlki rəsmi şərtlərdə göstərilən nəticələr tamdır.\n\n## Əvvəlki rəsmi tapşırıq tələbləri (dəyişməyib)\n## 1. Bu tapşırıq nə üçündür?\nAnalizi başqa şəxsin də eyni nəticəni ala biləcəyi şəkildə təşkil edib sənədləşdirəcəksən.\n\n## 2. Başlamazdan əvvəl\nÖz Tapşırıq 1–9 data layihən, notebook/SQL, dependency və data-source sənədləşdirməsi.\n\n## 3. Addım-addım icra\n1. Əvvəlki analizləri öz repo-n və ya notebook-da davam etdir.\n2. Qovluq quruluşunu, data source-u və quraşdırma addımlarını README-də yaz.\n3. Orijinal data və transform edilmiş data fərqini saxla; şəxsi/həssas məlumatı repo-ya yükləmə.\n4. Notebook-u təmiz kernel-dən başdan sona işə sal.\n5. SQL, data cleaning, chart və nəticələrin eyni qaydada yarandığını yoxla.\n6. Məlum limitlər və növbəti 3 təkmilləşdirməni qeyd et.\n\n## 4. Konkret nümunə və izah\nTəkrar icra yoxlaması: yeni qovluğa klonla, paket versiyalarını quraşdır, notebook-un yaddaşını sıfırla və bütün xanaları ardıcıllıqla işə sal. Yalnız Excel/Sheets istifadə edirsənsə, mənbə faylı və formulların yenilənmə addımlarını göstər.\n\n## 5. Nə təhvil verməlisən?\nÖz GitHub repo linkin, təkrar icra edilən notebook/SQL, README, data dictionary, nəticə faylları və clean-run sübutu. Başqa şəxs quraşdırma addımları ilə nəticəni təkrar yarada bilməlidir.\n\n## 6. Hazır olduğunu necə yoxlamalısan?\nYeni icrada eyni sətir sayları, KPI-lar və qrafiklər alınır. Lazım olan data mənbəsi, kitabxana versiyaları və əmrlər sənədləşib.\n\n[[EN]]\n## Beginner explanation\nThe goal is to produce **a real, verifiable outcome** rather than theory alone. **Example scenario:** Make cleaning and analysis reproducible from requirements.txt, clean.py and README.\n\n## Free tools and how to start\n- **Python (free)** — https://www.python.org. Install Python locally and run scripts with fictional test fixtures.\n- **GitHub Free** — https://github.com. Use a free repository with README and sample code; never commit secrets or personal data.\n- **Google Docs (personal)** — https://docs.google.com/document/. Create a document with goals, evidence, tables and a PDF export when needed.\n> No production data, paid hosting or premium subscription is required. Free quotas may change; use local tests and fictional data.\n\n## Step-by-step procedure (8 stages)\n1. Create a local `Talora / data-analytics / task-10` folder and reuse earlier fictional data or source files.\n2. Summarize the user, the problem and a verifiable success criterion in one sentence.\n3. Version fictional/licensed data, scripts and dependency requirements. Include evidence in a file, source code, sheet, diagram or screenshot.\n4. Document commands for a clean local rerun. Include evidence in a file, source code, sheet, diagram or screenshot.\n5. Verify outputs and charts match expectations and disclose limitations. Include evidence in a file, source code, sheet, diagram or screenshot.\n6. Complete this worked example: Make cleaning and analysis reproducible from requirements.txt, clean.py and README. Note one valid and one invalid/empty case.\n7. Prepare the deliverable required by the original instructions with editable sources, tests and a short README.\n8. Before submitting, check the original criteria and write a three-to-five sentence conclusion and limitations.\n\n## Practical worked example\nMake cleaning and analysis reproducible from requirements.txt, clean.py and README.\nAdapt the example to your own project, verify the result and do not present fictional statistics as real.\n\n## Required submission\n- **Main result:** the file, repository or link required by the unchanged original assignment below.\n- **Source and tests:** editable materials, appropriate code, fictional data, screenshots or test evidence.\n- **Explanation:** three to five sentences on findings, free tools and citations.\n- **Safety:** no passwords, API keys, private applications or unlicensed content.\n\n## Self-assessment rubric (100 points)\n- **40:** complete core actions and original deliverables.\n- **25:** measured, working result and invalid-case testing.\n- **15:** readable files, README and structure.\n- **10:** security, citations and free tools.\n- **10:** clear reasoning and suggested next steps.\n**Illustrative learning rubric only: it does not change official criteria or previously graded work.**\n\n## Before submission\n- Use local, fictional or properly authorized data.\n- Check links, exports and absence of confidential information.\n- Verify all original official requirements below.\n\n## Original official requirements (unchanged)\n## 1. Goal\nOrganize and document the analysis so another person can reproduce the same results.\n\n## 2. Before you start\nYour data project from Tasks 1–9, notebooks/SQL, dependencies, and data-source documentation.\n\n## 3. Step-by-step work\n1. Continue earlier analysis in your own repository or notebook.\n2. Document folder structure, data source, and setup in the README.\n3. Keep original and transformed data distinct; never commit personal/sensitive data.\n4. Run the notebook from top to bottom in a clean kernel.\n5. Verify SQL, cleaning, charts, and results are reproduced consistently.\n6. Record known limitations and the next three improvements.\n\n## 4. Concrete example and explanation\nReproduce from a new folder: install recorded package versions, restart the notebook kernel, and run cells in order. For Excel/Sheets, include source data and steps to refresh formulas.\n\n## 5. What to submit\nYour own GitHub repository link, reproducible notebook/SQL, README, data dictionary, output files, and clean-run evidence. Another person must be able to reproduce the results by following the setup steps.\n\n## 6. How to check your work\nA new run reproduces row counts, KPIs, and charts. Document data sources, dependency versions, and commands."}]$legacy_payload$::jsonb);
DO $preflight$
DECLARE n integer;
BEGIN
 SELECT count(*) INTO n FROM legacy_guides src CROSS JOIN LATERAL jsonb_array_elements(src.payload) e(item)
 JOIN public.internships i ON i.slug=e.item->>'slug'
 JOIN public.internship_tasks t ON t.internship_id=i.id AND t.task_number=(e.item->>'task_number')::integer
 WHERE i.slug='data-analytics' AND t.title=e.item->>'title' AND t.instructions=e.item->>'old_instructions'
 AND t.description=e.item->>'old_description' AND t.status='published' AND t.is_required;
 IF (SELECT jsonb_array_length(payload) FROM legacy_guides)<>10 OR n<>10 THEN RAISE EXCEPTION 'Version mismatch: data-analytics: %',n; END IF;
END; $preflight$;
DO $apply$
DECLARE n integer;
BEGIN
 UPDATE public.internship_tasks t SET instructions=e.item->>'new_instructions',description=e.item->>'new_description'
 FROM legacy_guides src CROSS JOIN LATERAL jsonb_array_elements(src.payload) e(item)
 JOIN public.internships i ON i.slug=e.item->>'slug'
 WHERE i.slug='data-analytics' AND t.internship_id=i.id AND t.task_number=(e.item->>'task_number')::integer
 AND t.title=e.item->>'title' AND t.instructions=e.item->>'old_instructions' AND t.description=e.item->>'old_description';
 GET DIAGNOSTICS n=ROW_COUNT;
 IF n<>10 THEN RAISE EXCEPTION 'Expected 10 updates for data-analytics, got %',n; END IF;
END; $apply$;
DO $verify$
DECLARE n integer;
BEGIN
 SELECT count(*) INTO n FROM legacy_guides src CROSS JOIN LATERAL jsonb_array_elements(src.payload) e(item)
 JOIN public.internships i ON i.slug=e.item->>'slug'
 JOIN public.internship_tasks t ON t.internship_id=i.id AND t.task_number=(e.item->>'task_number')::integer
 WHERE i.slug='data-analytics' AND t.instructions=e.item->>'new_instructions' AND t.description=e.item->>'new_description'
 AND t.status='published' AND t.is_required;
 IF n<>10 THEN RAISE EXCEPTION 'Post-update mismatch: data-analytics: %',n; END IF;
END; $verify$;
COMMIT;
